import type { T, Lang } from './lang';
import type { Guide } from './guides';

// Two more guides for /learn, on what people search for before they race: the points of sail, and how to tack and
// gybe. The same shape, voice and promise as lib/guides.ts: every claim about the game is what it does
// (public/game/sim.js, main.js, classes.js, world.js); change the game, change the guide.

// the rules guide on the Sailing Certification Test site, rule by rule
const rr = (lang: Lang, page: string) => `https://iyt.rycrentals.com${lang === 'ru' ? '/ru' : ''}/racing-rules/${page}`;

// the game's pictures, 1920 × 1440 unless said
const shot = (src: string, alt: string, width = 1920, height = 1440) => ({ src: `/images/${src}.jpg`, width, height, alt });

export function moreGuide(slug: 'sail' | 'tack', t: T, lang: Lang): Guide {
  if (slug === 'sail') return {
    slug,
    title: t('Points of sail: from close-hauled to a run', 'Курсы относительно ветра: от бейдевинда до фордевинда', 'Rumbos: de la ceñida a la empopada', 'Kurse zum Wind: von hoch am Wind bis zum Vorwindkurs', 'Seyir açıları: orsadan pupaya', 'Les allures : du près au vent arrière', 'Le andature: dalla bolina stretta alla poppa', 'Andaduras: da orça à popa'),
    short: t('Points of sail', 'Курсы относительно ветра', 'Rumbos', 'Kurse zum Wind', 'Seyir açıları', 'Les allures', 'Le andature', 'Andaduras'),
    kicker: t('Racing guides · points of sail', 'Пособия по гонкам · курсы', 'Guías de regata · rumbos', 'Regattaleitfäden · Kurse zum Wind', 'Yarış rehberleri · seyir açıları', 'Guides de régate · allures', 'Guide alla regata · andature', 'Guias de regata · andaduras'),
    img: shot('gd-sail-v2', t('Your boat close-hauled in the game, the fleet sailing upwind around her', 'Твоя лодка идёт в бейдевинд в игре, вокруг неё флот на лавировке', 'Tu barco de ceñida en el juego, con la flota navegando de ceñida a su alrededor', 'Dein Boot hoch am Wind im Spiel, das Feld segelt um es herum am Wind', 'Oyunda orsa giden teknen, etrafında orsa giden filo', 'Ton bateau au près dans le jeu, la flotte remontant au vent autour de lui', 'La tua barca di bolina stretta nel gioco, con la flotta che risale il vento intorno a lei', 'Seu barco na orça no jogo, com a flotilha velejando contra o vento ao redor'), 3840, 1600),
    description: t(
      'The points of sail: the no-go zone, close-hauled, reaching and running, how the sails are set on each, true and apparent wind, and which point is fastest.',
      'Курсы относительно ветра: мёртвый угол, бейдевинд, галфвинд, бакштаг и фордевинд, как ставить паруса, истинный и вымпельный ветер и какой курс быстрее.', 'Los rumbos: la zona prohibida, la ceñida, el través y la empopada, cómo se ponen las velas en cada uno, viento real y aparente, y qué rumbo es el más rápido.', 'Die Kurse zum Wind: die Windkeule, hoch am Wind, raumschots und vor dem Wind, wie die Segel auf jedem gesetzt sind, wahrer und scheinbarer Wind und welcher Kurs am schnellsten ist.', 'Seyir açıları: yelken açılamayan bölge, orsa, apaz ve pupa, yelkenlerin her birinde nasıl ayarlandığı, gerçek ve görünen rüzgâr ve hangi açının en hızlı olduğu.', 'Les allures : la zone interdite, le près, le largue et le vent arrière, le réglage des voiles à chacune, vent réel et vent apparent, et quelle allure est la plus rapide.', 'Le andature: il settore morto, la bolina stretta, il lasco e la poppa, come si regolano le vele in ognuna, vento reale e vento apparente, e qual è l’andatura più veloce.', 'As andaduras: o setor proibido, a orça, o través e a popa, como as velas ficam em cada uma, vento real e vento aparente, e qual andadura é a mais rápida.'),
    intro: t(
      'A boat’s point of sail is her angle to the wind, and it decides almost everything else: how the sails are set, how fast she goes and whether she can sail where you want at all. There are five to know, from close-hauled, as near the wind as she will go, round to a run, with the wind behind her.',
      'Курс относительно ветра — это угол лодки к ветру, и от него зависит почти всё остальное: как стоят паруса, как быстро она идёт и может ли вообще идти туда, куда тебе нужно. Знать надо пять курсов: от бейдевинда, так круто к ветру, как она ещё идёт, до фордевинда, когда ветер дует сзади.', 'El rumbo de un barco es su ángulo con el viento, y decide casi todo lo demás: cómo se ponen las velas, qué velocidad alcanza y si puede navegar hacia donde quieres. Hay cinco que conocer, desde la ceñida, lo más cerca del viento que puede ir, hasta la empopada, con el viento por detrás.', 'Der Kurs eines Bootes zum Wind ist sein Winkel zum Wind, und er entscheidet fast alles andere: wie die Segel gesetzt sind, wie schnell es fährt und ob es überhaupt dorthin segeln kann, wohin du willst. Fünf muss man kennen, von hoch am Wind, so nah am Wind, wie es geht, bis zum Vorwindkurs, mit dem Wind von hinten.', 'Bir teknenin seyir açısı rüzgâra olan açısıdır ve neredeyse her şeyi belirler: yelkenlerin nasıl ayarlanacağını, teknenin ne kadar hızlı gideceğini ve istediğin yere hiç gidip gidemeyeceğini. Bilmen gereken beş tane var: rüzgâra gidebildiği kadar yakın olduğu orsadan, rüzgârın arkada olduğu pupaya kadar.', 'L’allure d’un bateau, c’est son angle par rapport au vent, et elle décide de presque tout le reste : le réglage des voiles, sa vitesse et s’il peut seulement aller là où tu veux. Il y en a cinq à connaître, du près, aussi près du vent qu’il peut aller, jusqu’au vent arrière, le vent dans le dos.', 'L’andatura di una barca è il suo angolo rispetto al vento, e decide quasi tutto il resto: come si regolano le vele, quanto va veloce e se può davvero andare dove vuoi tu. Ce ne sono cinque da conoscere, dalla bolina stretta, il più vicino al vento che riesce ad andare, fino alla poppa, con il vento alle spalle.', 'A andadura de um barco é o ângulo dele em relação ao vento, e ela decide quase todo o resto: como as velas ficam, a velocidade e se ele consegue mesmo ir aonde você quer. São cinco para conhecer, da orça, o mais perto do vento que ele vai, até a popa, com o vento por trás.'),
    sections: [
      { id: 'nogo', h: t('The no-go zone', 'Мёртвый угол', 'La zona prohibida', 'Die Windkeule', 'Yelken açılamayan bölge', 'La zone interdite', 'Il settore morto', 'O setor proibido'), p: [
        t('No sailing boat can sail straight into the wind. Point within about 40° to 45° of it on either side and the sails flap and she stops. That arc, some 90° wide, is the no-go zone; a boat stuck head to wind in it, unable to steer, is in irons.',
          'Прямо против ветра не может идти ни одна парусная лодка. Направь нос ближе чем на 40–45° к ветру с любой стороны — паруса заполощут, и лодка остановится. Эта дуга шириной около 90° — мёртвый угол; лодка, которая встала в нём носом к ветру и не слушается руля, — в левентике.', 'Ningún velero puede navegar directo contra el viento. Apunta a menos de unos 40° a 45° de él, a cada lado, y las velas aletean y se para. Ese arco, de unos 90° de ancho, es la zona prohibida; un barco atascado proa al viento en ella, sin poder gobernar, está parado proa al viento.', 'Kein Segelboot kann direkt gegen den Wind segeln. Liegt der Bug innerhalb von etwa 40° bis 45° zum Wind, auf beiden Seiten, flattern die Segel, und es bleibt stehen. Dieser Bogen, rund 90° breit, ist die Windkeule; ein Boot, das darin mit dem Bug im Wind festhängt und nicht steuern kann, steht im Wind.', 'Hiçbir yelkenli doğrudan rüzgâra yelken açamaz. İki yanda da rüzgârdan yaklaşık 40° ile 45° içinde dümen tutarsan yelkenler çırpınır ve tekne durur. Yaklaşık 90° genişliğindeki bu yay, yelken açılamayan bölgedir; içinde rüzgâra dönük kalıp dümen tutamayan tekne rüzgâra dikilmiştir.', 'Aucun voilier ne peut remonter droit dans le vent. Pointe à moins de 40° à 45° de lui, d’un côté ou de l’autre, et les voiles faseyent et il s’arrête. Cet arc d’environ 90° de large, c’est la zone interdite ; un bateau bloqué face au vent, incapable de manœuvrer, est vent debout.', 'Nessuna barca a vela può andare dritta controvento. Punta a meno di 40°–45° dal vento, da un lato o dall’altro, e le vele sbattono e la barca si ferma. Quell’arco, largo circa 90°, è il settore morto; una barca bloccata lì prua al vento, senza poter governare, è nell’angolo morto.', 'Nenhum veleiro consegue velejar direto contra o vento. Aponte a menos de uns 40° a 45° dele, de qualquer lado, e as velas panejam e o barco para. Esse arco, de uns 90° de largura, é o setor proibido; um barco preso de proa ao vento dentro dele, sem governo, está aproado.'),
        t('So to reach a mark that lies upwind she sails a zigzag, close-hauled on one tack and then on the other: a beat. In the game the red arc round your boat is the no-go zone for the wind you’re in, and the green marks at its ends are close-hauled on each tack.',
          'Поэтому к знаку, который лежит против ветра, лодка идёт зигзагом, в бейдевинд то одним галсом, то другим, — это лавировка. В игре красная дуга вокруг лодки — мёртвый угол для текущего ветра, а зелёные метки на её концах — бейдевинд на каждом галсе.', 'Así que para llegar a una baliza que queda a barlovento navega en zigzag, de ceñida por una amura y luego por la otra: una ceñida. En el juego, el arco rojo alrededor de tu barco es la zona prohibida para el viento en que estás, y las marcas verdes en sus extremos son la ceñida en cada amura.', 'Um also eine Bahnmarke in Luv zu erreichen, segelt es im Zickzack, hoch am Wind erst auf dem einen Bug, dann auf dem anderen: ein Kreuz. Im Spiel ist der rote Bogen um dein Boot die Windkeule für den Wind, in dem du bist, und die grünen Marken an seinen Enden sind hoch am Wind auf jedem Bug.', 'Bu yüzden rüzgârüstünde bulunan bir şamandıraya ulaşmak için zikzak çizer, önce bir kontrada sonra öbüründe orsa giderek: bir orsa ayağı. Oyunda teknenin etrafındaki kırmızı yay, içinde bulunduğun rüzgâr için yelken açılamayan bölgedir; uçlarındaki yeşil işaretler her kontradaki orsadır.', 'Pour atteindre une bouée au vent, il remonte donc en zigzag, au près sur un bord puis sur l’autre : il tire des bords. Dans le jeu, l’arc rouge autour de ton bateau est la zone interdite pour le vent où tu es, et les repères verts à ses extrémités marquent le près sur chaque amure.', 'Così, per raggiungere una boa che si trova sopravvento, la barca procede a zigzag, di bolina stretta prima con una mura e poi con l’altra: bordeggia. Nel gioco l’arco rosso intorno alla tua barca è il settore morto per il vento in cui sei, e i segni verdi alle sue estremità indicano la bolina stretta su ciascuna mura.', 'Então, para chegar a uma boia que fica a barlavento, ele veleja em ziguezague, na orça em uma amura e depois na outra: um bordejo. No jogo, o arco vermelho em volta do seu barco é o setor proibido para o vento em que você está, e as marcas verdes nas pontas dele são a orça em cada amura.'),
      ], tip: t('In irons, let the sheets out and hold the jib out to one side: the wind pushes the bow off the other way, and once the sails fill you can pull them in and sail off. In the game, steer away from the wind.',
        'Встал в левентик — потрави шкоты и вынеси стаксель на один борт: ветер оттолкнёт нос в другую сторону, а когда паруса наполнятся, выбери их и уходи. В игре просто рули от ветра.', 'Parado proa al viento, suelta las escotas y mantén el foque abierto hacia un lado: el viento empuja la proa hacia el otro, y cuando las velas se llenan puedes cazarlas y salir navegando. En el juego, gobierna lejos del viento.', 'Wenn du im Wind stehst, fiere die Schoten und halte die Fock zu einer Seite hinaus: Der Wind drückt den Bug auf die andere Seite, und sobald die Segel füllen, kannst du sie dichtholen und losfahren. Im Spiel steuere vom Wind weg.', 'Rüzgâra dikildiğinde iskotaları bırak ve flokü bir yana açık tut: rüzgâr pruvayı öbür yana iter ve yelkenler dolunca çekip yola çıkabilirsin. Oyunda rüzgârdan uzaklaş.', 'Vent debout, choque les écoutes et tiens le foc à contre d’un côté : le vent repousse l’étrave de l’autre côté, et dès que les voiles portent tu peux les border et repartir. Dans le jeu, abats.', 'Nell’angolo morto, lasca le scotte e tieni il fiocco aperto da un lato: il vento spinge la prua dall’altra parte, e appena le vele si riempiono puoi cazzarle e ripartire. Nel gioco, poggia.', 'Aproado, folgue as escotas e segure a buja aberta para um lado: o vento empurra a proa para o outro lado e, quando as velas enchem, você pode caçá-las e sair velejando. No jogo, arribe.') },
      { id: 'close', h: t('Close-hauled and the close reach', 'Бейдевинд и полный бейдевинд', 'La ceñida y la ceñida holgada', 'Hoch am Wind und der angeluvte Halbwindkurs', 'Orsa ve dar apaz', 'Le près et le bon plein', 'La bolina stretta e la bolina larga', 'A orça e a bolina folgada'), p: [
        t('Close-hauled is as near the wind as the boat sails well: about 45° off the true wind for most cruisers and dinghies, nearer 40° for a racing keelboat. The sails are pulled in hard, the boom near the middle of the boat and the jib close in. Point higher and she pinches: the front of the jib lifts, and she slows and slips sideways.',
          'Бейдевинд — так круто к ветру, как лодка ещё хорошо идёт: около 45° к истинному ветру у большинства крейсерских яхт и швертботов и ближе к 40° у гоночной килевой лодки. Паруса выбраны туго, гик почти над серединой лодки, стаксель прижат. Пойдёшь круче — передняя кромка стакселя заполощет, лодка замедлится и начнёт сползать вбок.', 'De ceñida es lo más cerca del viento que el barco navega bien: unos 45° del viento real en la mayoría de los cruceros y derivas, más cerca de 40° en una quilla de regata. Las velas van cazadas a fondo, la botavara cerca del centro del barco y el foque pegado. Si apuntas más alto, ciñe de más: el borde de ataque del foque se levanta, y se frena y se desliza de lado.', 'Hoch am Wind ist so nah am Wind, wie das Boot gut segelt: etwa 45° zum wahren Wind bei den meisten Fahrtenyachten und Jollen, eher 40° bei einem Regatta-Kielboot. Die Segel sind hart dicht geholt, der Baum nahe der Bootsmitte und die Fock dicht. Fährst du höher, kneift es: Das Vorliek der Fock beginnt zu killen, und es wird langsamer und rutscht seitlich ab.', 'Orsa, teknenin iyi yelken açtığı kadar rüzgâra yakın seyirdir: çoğu gezi teknesi ve dinghy için gerçek rüzgârdan yaklaşık 45°, bir yarış omurgalısı için 40° civarı. Yelkenler sonuna kadar çekilir, bom teknenin ortasına yakın, flok içeride. Daha yükseğe dümen tutarsan tekne sıkışır: flokün ön kısmı kalkar, tekne yavaşlar ve yana kayar.', 'Le près, c’est aussi près du vent que le bateau avance bien : environ 45° du vent réel pour la plupart des croiseurs et des dériveurs, plutôt 40° pour un quillard de course. Les voiles sont bordées à fond, la bôme près de l’axe du bateau et le foc serré. Lofe davantage et il pince : le guindant du foc se soulève, et il ralentit et dérape.', 'La bolina stretta è il più vicino al vento che la barca riesce a navigare bene: circa 45° dal vento reale per la maggior parte delle barche da crociera e delle derive, più vicino ai 40° per una barca a chiglia da regata. Le vele sono cazzate a fondo, il boma vicino al centro della barca e il fiocco stretto. Stringi di più e la barca pizzica: il bordo d’entrata del fiocco si sventa, e lei rallenta e scarroccia.', 'Na orça é o mais perto do vento que o barco veleja bem: uns 45° do vento real para a maioria dos barcos de cruzeiro e dos dingues, mais perto de 40° para um barco de quilha de regata. As velas ficam bem caçadas, a retranca perto do centro do barco e a buja fechada. Orce mais e ele belisca: a testa da buja levanta, e ele perde velocidade e escorrega de lado.'),
        t('Bear away a little further and ease the sheets a little, and she is on a close reach: she points lower than close-hauled, but goes faster.',
          'Увались ещё немного, чуть потрави шкоты — и ты в полный бейдевинд: лодка идёт ниже, чем в крутой бейдевинд, зато быстрее.', 'Arriba un poco más y suelta algo las escotas, y va en una ceñida holgada: apunta más bajo que de ceñida, pero va más rápido.', 'Fall noch etwas weiter ab und fiere die Schoten etwas, und es liegt auf einem angeluvten Halbwindkurs: Es fährt tiefer als hoch am Wind, aber schneller.', 'Biraz daha boşla ve iskotaları biraz gevşet; tekne dar apazdadır: orsadan daha aşağı gider ama daha hızlıdır.', 'Abats encore un peu et choque un peu les écoutes : il est au bon plein. Il serre moins le vent qu’au près, mais va plus vite.', 'Poggia ancora un po’ e lasca un po’ le scotte, ed eccola di bolina larga: stringe meno che di bolina stretta, ma va più veloce.', 'Arribe mais um pouco e folgue um pouco as escotas, e ele está em bolina folgada: aponta mais baixo que na orça, mas anda mais rápido.'),
      ], tip: t('Steer close-hauled by the jib: head up until its front edge just starts to lift, then bear away a touch until it stops. That edge is the edge of the no-go zone, and it moves with every shift.',
        'В бейдевинд рули по стакселю: приводись, пока его передняя кромка не начнёт заполаскивать, потом чуть увались, пока не перестанет. Эта кромка и есть граница мёртвого угла, и она сдвигается с каждым сдвигом ветра.', 'Gobierna de ceñida con el foque: orza hasta que su borde de ataque empiece a levantarse, y luego arriba un poco hasta que pare. Ese borde es el borde de la zona prohibida, y se mueve con cada rolada.', 'Steuere hoch am Wind nach der Fock: luv an, bis ihre Vorderkante gerade anfängt zu killen, dann fall ein wenig ab, bis es aufhört. Diese Kante ist die Kante der Windkeule, und sie wandert mit jedem Winddreher.', 'Orsayı flokle yönet: ön kenarı tam kalkmaya başlayana kadar orsala, sonra durana kadar bir parça boşla. O kenar yelken açılamayan bölgenin kenarıdır ve her rüzgâr dönüşünde hareket eder.', 'Barre au près au foc : lofe jusqu’à ce que son guindant commence tout juste à se soulever, puis abats un poil jusqu’à ce qu’il s’arrête. Ce guindant marque le bord de la zone interdite, et il bouge à chaque bascule.', 'Di bolina stretta governa guardando il fiocco: orza finché il bordo d’entrata non comincia appena a sventarsi, poi poggia un filo finché smette. Quel bordo è il limite del settore morto, e si sposta a ogni salto di vento.', 'Na orça, guie-se pela buja: orce até a testa dela começar a levantar e então arribe um pouquinho até parar. Essa testa marca a borda do setor proibido, e ela se move a cada rondada.') },
      { id: 'reach', h: t('Reaching: beam and broad', 'Галфвинд и бакштаг', 'Navegar de través: través y largo', 'Raumschots: Halbwind und Raumwind', 'Apaz: yan ve geniş', 'Le largue : travers et grand largue', 'Il lasco: al traverso e gran lasco', 'Velejar de través: través e largo'), p: [
        t('A reach is a course across the wind. On a beam reach the wind comes square over the side, at 90°, and the sails are let out about halfway. On a broad reach it comes over the back quarter, between the beam and the stern, and they go out further still, the boom well out over the side.',
          'В галфвинд и бакштаг ветер дует сбоку. В галфвинд ветер дует ровно в борт, под 90°, и паруса потравлены примерно наполовину. В бакштаг он дует сзади-сбоку, между траверзом и кормой, и паруса потравлены ещё больше, гик далеко за бортом.', 'Un través es un rumbo cruzado al viento. En un través el viento entra perpendicular al costado, a 90°, y las velas van sueltas hasta la mitad. En un largo entra por la aleta, entre el través y la popa, y salen todavía más, con la botavara bien fuera por el costado.', 'Ein Raumschotskurs ist ein Kurs quer zum Wind. Auf einem Halbwindkurs kommt der Wind rechtwinklig über die Seite, bei 90°, und die Segel sind etwa halb gefiert. Auf einem Raumwindkurs kommt er über die hintere Seite, zwischen Querab und Heck, und sie werden noch weiter gefiert, der Baum weit über die Seite hinaus.', 'Apaz, rüzgârı enine alan seyirdir. Yan apazda rüzgâr yandan, 90° ile gelir ve yelkenler yaklaşık yarıya kadar bırakılır. Geniş apazda rüzgâr kıç omuzluktan, yan ile kıç arasından gelir ve yelkenler daha da açılır, bom yanın çok dışına çıkar.', 'Le largue, c’est une route en travers du vent. Au vent de travers, le vent arrive pile sur le côté, à 90°, et les voiles sont choquées à peu près à moitié. Au grand largue, il arrive par la hanche, entre le travers et l’arrière, et elles sont choquées encore plus, la bôme bien sortie au-dessus du bord.', 'Il lasco è una rotta attraverso il vento. Al traverso il vento arriva dritto sul fianco, a 90°, e le vele sono lascate più o meno a metà. Al gran lasco arriva dal giardinetto, tra il traverso e la poppa, e si lascano ancora di più, con il boma ben fuori bordo.', 'Velejar de través é seguir um rumo cruzando o vento. No través, o vento entra bem pelo lado, a 90°, e as velas ficam folgadas mais ou menos até a metade. No largo, ele entra pela alheta, entre o través e a popa, e elas são folgadas ainda mais, com a retranca bem para fora do barco.'),
        t('On any reach the way to set a sail is the same: ease it until its front edge just starts to flap, then pull it back in until it stops. In a dinghy the centreboard goes up as you bear away: all the way down close-hauled, about halfway on a beam reach, mostly up on a run.',
          'На любом из этих курсов парус ставят одинаково: трави, пока передняя кромка не начнёт заполаскивать, потом выбирай, пока не перестанет. На швертботе шверт поднимают по мере того, как уваливаются: в бейдевинд он опущен полностью, в галфвинд — наполовину, на фордевинде почти поднят.', 'En cualquier través la forma de poner una vela es la misma: suéltala hasta que su borde de ataque empiece a aletear y luego cázala hasta que pare. En una deriva la orza sube a medida que arribas: toda abajo de ceñida, a la mitad en un través, casi toda arriba en una empopada.', 'Auf jedem Raumschotskurs ist die Art, ein Segel zu setzen, dieselbe: fiere es, bis seine Vorderkante gerade anfängt zu flattern, dann hol es wieder dicht, bis es aufhört. In einer Jolle geht das Schwert hoch, wenn du abfällst: ganz unten hoch am Wind, etwa halb auf einem Halbwindkurs, meist oben vor dem Wind.', 'Her apazda yelken ayarının yolu aynıdır: ön kenarı tam çırpınmaya başlayana kadar bırak, sonra durana kadar geri çek. Dinghy’de boşladıkça kılıç yukarı çıkar: orsada sonuna kadar aşağıda, yan apazda yaklaşık yarıda, pupada çoğunlukla yukarıda.', 'À toutes les allures de largue, une voile se règle de la même façon : choque-la jusqu’à ce que son guindant commence tout juste à faseyer, puis borde-la jusqu’à ce qu’il s’arrête. En dériveur, on remonte la dérive en abattant : à fond au près, à moitié environ au travers, presque entièrement remontée au vent arrière.', 'A qualsiasi andatura di lasco una vela si regola allo stesso modo: lascala finché il bordo d’entrata non comincia appena a sbattere, poi cazzala finché smette. In una deriva, la deriva si alza man mano che poggi: tutta giù di bolina stretta, circa a metà al traverso, quasi tutta su in poppa.', 'Em qualquer través, a vela se regula do mesmo jeito: folgue até a testa começar a panejar, depois cace de volta até parar. Num dingue, a bolina sobe conforme você arriba: toda para baixo na orça, mais ou menos pela metade no través, quase toda para cima na popa.'),
      ], tip: t('In the game the Kite button sets the gennaker once the wind is more than 100° off the bow, and it comes down in a hurry if you head up much above a beam reach with it set.',
        'В игре кнопка «Генакер» ставит генакер, когда ветер дует больше чем на 100° от носа, а если с поднятым генакером привестись заметно круче галфвинда, его в спешке убирают.', 'En el juego el botón Kite ica el gennaker cuando el viento está a más de 100° de la proa, y se arría de golpe si orzas bastante por encima de un través con él izado.', 'Im Spiel setzt der Spi-Knopf den Gennaker, sobald der Wind mehr als 100° vom Bug kommt, und er kommt eilig herunter, wenn du mit ihm oben viel höher als Halbwind luvst.', 'Oyunda Balon düğmesi, rüzgâr pruvadan 100°’den fazla açıyla geldiğinde gennaker’ı açar; açıkken yan apazın hayli üzerine orsalarsan hızla iner.', 'Dans le jeu, le bouton Kite envoie le gennaker dès que le vent est à plus de 100° de l’étrave, et il descend en catastrophe si tu lofes nettement au-dessus du travers avec lui.', 'Nel gioco il pulsante Kite issa il gennaker appena il vento è a più di 100° dalla prua, e viene giù in fretta se con il gennaker issato orzi molto oltre il traverso.', 'No jogo, o botão Gennaker iça o gennaker assim que o vento passa de 100° da proa, e ele desce às pressas se você orçar bem acima do través com ele içado.') },
      { id: 'run', h: t('Running', 'Фордевинд', 'Empopada', 'Vor dem Wind', 'Pupa', 'Le vent arrière', 'La poppa', 'Popa'), p: [
        t('On a run the wind is behind you and the boat is pushed rather than pulled along. The main is let right out, the boom square across the boat, short of the shrouds. The jib, in the main’s wind shadow, goes limp: you can hold it out on the other side, goose-winged, or set a spinnaker or a gennaker instead.',
          'На фордевинде ветер дует сзади, и лодку не тянет, а толкает. Грот потравлен до конца, гик стоит поперёк лодки, не доходя до вант. Стаксель в ветровой тени грота обвисает: его можно вынести на другой борт — поставить паруса «бабочкой» — или вместо него поставить спинакер или генакер.', 'En una empopada el viento está detrás de ti y el barco va empujado en lugar de tirado. La mayor va suelta del todo, la botavara perpendicular al barco, sin llegar a los obenques. El foque, en la sombra de viento de la mayor, queda flojo: puedes mantenerlo abierto por el otro lado, a mariposa, o izar un spinnaker o un gennaker en su lugar.', 'Vor dem Wind liegt der Wind hinter dir, und das Boot wird eher geschoben als gezogen. Das Groß ist ganz gefiert, der Baum quer über dem Boot, vor den Wanten. Die Fock im Windschatten des Großsegels fällt in sich zusammen: Du kannst sie auf der anderen Seite ausbaumen, als Schmetterling, oder stattdessen einen Spinnaker oder einen Gennaker setzen.', 'Pupada rüzgâr arkandadır ve tekne çekilmekten çok itilir. Ana sonuna kadar bırakılır, bom tekneyi enine keser, babalara varmadan. Ananın rüzgâr gölgesindeki flok gevşer: onu öbür yana açık tutabilirsin, kelebek, ya da onun yerine balon ya da gennaker açabilirsin.', 'Au vent arrière, le vent est dans ton dos et le bateau est poussé plutôt que tiré. La grand-voile est choquée en grand, la bôme perpendiculaire au bateau, juste avant les haubans. Le foc, dans le dévent de la grand-voile, pend mollement : tu peux le tangonner de l’autre côté, en ciseaux, ou envoyer à la place un spi ou un gennaker.', 'In poppa il vento è alle tue spalle e la barca viene spinta più che tirata. La randa è lascata del tutto, il boma perpendicolare alla barca, poco prima delle sartie. Il fiocco, nella copertura della randa, si affloscia: puoi tenerlo aperto dall’altro lato, a farfalla, oppure issare al suo posto uno spinnaker o un gennaker.', 'Na popa, o vento vem por trás e o barco é empurrado em vez de puxado. A vela grande fica toda folgada, a retranca perpendicular ao barco, antes dos brandais. A buja, na sombra de vento da grande, fica murcha: você pode abri-la do outro lado, em asa de pombo, ou içar um balão ou um gennaker no lugar dela.'),
        t('Bear away past dead downwind and the wind gets behind the main from the other side: you are sailing by the lee, and the boom can come across on its own. So most boats, and all with an asymmetric gennaker, sail a few degrees either side of dead downwind and gybe between them.',
          'Увалишься дальше чистого фордевинда — ветер зайдёт за грот с другой стороны, и гик может перебросить сам. Поэтому большинство лодок, а с асимметричным генакером все, идут на несколько градусов в сторону от чистого фордевинда и делают между этими углами повороты фордевинд.', 'Si arribas más allá de la popa total, el viento entra por detrás de la mayor desde el otro lado: navegas por la contra, y la botavara puede cruzar sola. Así que la mayoría de los barcos, y todos los de gennaker asimétrico, navegan unos grados a cada lado de la popa total y trasluchan entre ellos.', 'Fällst du über den Vorwindkurs hinaus ab, kommt der Wind von der anderen Seite hinter das Groß: Du segelst „by the lee“, und der Baum kann von allein hinüberschlagen. Die meisten Boote, und alle mit einem asymmetrischen Gennaker, segeln deshalb ein paar Grad zu beiden Seiten des Vorwindkurses und halsen dazwischen.', 'Tam pupanın ötesine boşlarsan rüzgâr ananın arkasına öbür yandan gelir: lee’den yelken açıyorsun ve bom kendiliğinden öbür yana geçebilir. Bu yüzden çoğu tekne ve asimetrik gennakerli olanların hepsi, tam pupanın iki yanında birkaç derece yelken açar ve aralarında kavança atar.', 'Abats au-delà du plein vent arrière et le vent passe derrière la grand-voile par l’autre côté : tu navigues sur la panne, et la bôme peut passer toute seule. C’est pourquoi la plupart des bateaux, et tous ceux qui ont un gennaker asymétrique, naviguent quelques degrés de part et d’autre du plein vent arrière et empannent entre les deux.', 'Poggia oltre la poppa piena e il vento passa dietro la randa dall’altro lato: stai navigando alla strapoggia, e il boma può passare da solo. Per questo la maggior parte delle barche, e tutte quelle con un gennaker asimmetrico, navigano qualche grado da una parte o dall’altra della poppa piena e strambano tra l’una e l’altra.', 'Arribe além da popa rasa e o vento passa por trás da vela grande pelo outro lado: você está navegando de popa rasa, e a retranca pode cruzar sozinha. Por isso a maioria dos barcos, e todos com gennaker assimétrico, velejam alguns graus para um lado ou outro da popa rasa e jibam entre eles.'),
      ], tip: t('In the game the blue marks round your boat are the best angle downwind on each gybe for the wind you’re in; between them, dead downwind, she is slower.',
        'В игре синие метки вокруг лодки — лучший угол на попутном курсе на каждом галсе для текущего ветра; между ними, на чистом фордевинде, лодка идёт медленнее.', 'En el juego las marcas azules alrededor de tu barco son el mejor ángulo de popa en cada amura para el viento en que estás; entre ellas, en popa total, va más lento.', 'Im Spiel sind die blauen Marken um dein Boot der beste Winkel vor dem Wind auf jeder Halse für den Wind, in dem du bist; dazwischen, direkt vor dem Wind, ist das Boot langsamer.', 'Oyunda teknenin etrafındaki mavi işaretler, içinde bulunduğun rüzgâr için her kavançadaki en iyi pupa açısıdır; aralarında, tam pupada, tekne daha yavaştır.', 'Dans le jeu, les repères bleus autour de ton bateau marquent le meilleur angle au portant sur chaque amure pour le vent où tu es ; entre eux, au plein vent arrière, il est plus lent.', 'Nel gioco i segni blu intorno alla tua barca indicano il miglior angolo in poppa su ciascuna mura per il vento in cui sei; tra i due, in poppa piena, la barca è più lenta.', 'No jogo, as marcas azuis em volta do seu barco são o melhor ângulo em popa em cada amura para o vento em que você está; entre elas, em popa rasa, ele fica mais lento.') },
      { id: 'apparent', h: t('True and apparent wind', 'Истинный и вымпельный ветер', 'Viento real y aparente', 'Wahrer und scheinbarer Wind', 'Gerçek ve görünen rüzgâr', 'Vent réel et vent apparent', 'Vento reale e vento apparente', 'Vento real e vento aparente'), p: [
        t('The true wind is the one you feel standing still. Once the boat moves she makes a wind of her own, from dead ahead, as you feel on a bicycle, and the two together are the apparent wind: the one the sails feel and the masthead wind indicator shows. It always blows from further forward than the true wind, except dead downwind. Upwind and across the wind it is stronger; downwind it is weaker, which is why a run feels gentler than it is.',
          'Истинный ветер — тот, что чувствуешь, стоя на месте. Когда лодка движется, она создаёт свой встречный ветер, как на велосипеде, и вместе они дают вымпельный ветер — тот, что чувствуют паруса и показывает флюгер на топе мачты. Он всегда дует ближе к носу, чем истинный, кроме чистого фордевинда. На лавировке и в галфвинд он сильнее истинного, на попутном курсе — слабее, поэтому на фордевинде ветер кажется тише, чем есть.', 'El viento real es el que sientes parado. Cuando el barco se mueve crea un viento propio, de proa, como el que notas en una bicicleta, y los dos juntos son el viento aparente: el que sienten las velas y marca la veleta del tope del mástil. Siempre sopla de más a proa que el viento real, salvo en popa total. De ceñida y de través es más fuerte; de popa es más débil, por eso una empopada parece más suave de lo que es.', 'Der wahre Wind ist der, den du spürst, wenn du still stehst. Sobald das Boot sich bewegt, macht es einen eigenen Wind, genau von vorn, wie du ihn auf dem Fahrrad spürst, und beide zusammen sind der scheinbare Wind: der, den die Segel spüren und den der Verklicker im Masttop zeigt. Er weht immer von weiter vorn als der wahre Wind, außer genau vor dem Wind. Am Wind und quer zum Wind ist er stärker; vor dem Wind ist er schwächer, weshalb sich ein Vorwindkurs sanfter anfühlt, als er ist.', 'Gerçek rüzgâr, olduğun yerde dururken hissettiğin rüzgârdır. Tekne hareket etmeye başlayınca kendi rüzgârını yaratır, tam önden, bisikletteki gibi, ve ikisi bir araya gelince görünen rüzgâr olur: yelkenlerin hissettiği ve direk başı rüzgâr göstergesinin gösterdiği. Tam pupa dışında gerçek rüzgârdan her zaman daha ileriden eser. Orsada ve rüzgârı enine alırken daha güçlüdür; pupada daha zayıftır, bu yüzden pupa gerçekte olduğundan daha yumuşak hissedilir.', 'Le vent réel, c’est celui que tu sens à l’arrêt. Dès que le bateau avance, il crée son propre vent, venu de l’avant, comme à vélo, et les deux ensemble font le vent apparent : celui que sentent les voiles et que montre la girouette en tête de mât. Il vient toujours de plus en avant que le vent réel, sauf au plein vent arrière. Au près et au travers il est plus fort ; au portant il est plus faible, c’est pourquoi le vent arrière paraît plus doux qu’il ne l’est.', 'Il vento reale è quello che senti stando fermo. Appena la barca si muove crea un vento suo, da prua, come quello che senti in bicicletta, e i due insieme sono il vento apparente: quello che sentono le vele e che mostra l’indicatore del vento in testa d’albero. Arriva sempre più da prua del vento reale, tranne in poppa piena. Di bolina e al traverso è più forte; nelle andature portanti è più debole, ed è per questo che la poppa sembra più tranquilla di quanto sia.', 'O vento real é o que você sente parado. Assim que o barco anda, ele cria um vento próprio, vindo bem de proa, como você sente numa bicicleta, e os dois juntos formam o vento aparente: o que as velas sentem e o que a biruta no topo do mastro mostra. Ele sempre sopra mais de proa que o vento real, exceto em popa rasa. Na orça e no través ele é mais forte; na popa é mais fraco, e por isso a popa parece mais tranquila do que é.'),
        t('The sails are trimmed to the apparent wind, so it moves the sheets. As she speeds up it swings forward and you pull in. In a gust it swings aft for a moment: upwind she can point a little higher, downwind go a little deeper. The faster the boat, the further forward it comes: the AC75 in the game, on her foils, sails at three times the wind’s speed, and her apparent wind stays ahead even heading downwind.',
          'Паруса настраивают по вымпельному ветру, и он двигает шкоты. Лодка разгоняется — он смещается к носу, и шкот надо выбрать. В порыве он на время смещается к корме: на лавировке можно идти чуть круче, на попутном — чуть глубже. Чем быстрее лодка, тем дальше к носу он заходит: AC75 в игре на крыльях идёт втрое быстрее ветра, и её вымпельный ветер остаётся впереди даже на попутном курсе.', 'Las velas se ajustan según el viento aparente, así que mueve las escotas. A medida que acelera, se abre hacia proa y cazas. En una racha se abre hacia popa un momento: de ceñida puede apuntar un poco más alto, de popa ir un poco más abierta. Cuanto más rápido el barco, más a proa viene: el AC75 del juego, sobre sus foils, navega al triple de la velocidad del viento, y su viento aparente se queda por delante incluso rumbo a popa.', 'Die Segel werden nach dem scheinbaren Wind getrimmt, er bewegt also die Schoten. Wird das Boot schneller, dreht er nach vorn und du holst dicht. In einer Bö dreht er für einen Moment nach achtern: Am Wind kann es etwas höher fahren, vor dem Wind etwas tiefer. Je schneller das Boot, desto weiter kommt er von vorn: Die AC75 im Spiel segelt auf ihren Foils mit dem Dreifachen der Windgeschwindigkeit, und ihr scheinbarer Wind bleibt vorn, auch wenn sie vor dem Wind fährt.', 'Yelkenler görünen rüzgâra göre trim edilir, bu yüzden iskotaları o oynatır. Tekne hızlandıkça öne döner ve sen çekersin. Bir hamlede bir an geriye döner: orsada tekne biraz daha yükseğe gidebilir, pupada biraz daha derine. Tekne ne kadar hızlıysa o kadar öne gelir: oyundaki AC75, foillerinin üzerinde, rüzgârın üç katı hızla gider ve görünen rüzgârı pupaya giderken bile önde kalır.', 'Les voiles se règlent sur le vent apparent, c’est donc lui qui fait bouger les écoutes. Quand le bateau accélère, il refuse et tu bordes. Dans une risée, il adonne un instant : au près tu peux lofer un peu, au portant abattre un peu plus. Plus le bateau est rapide, plus il vient de l’avant : l’AC75 du jeu, sur ses foils, va trois fois plus vite que le vent, et son vent apparent reste devant même au portant.', 'Le vele si regolano sul vento apparente, ed è lui a muovere le scotte. Quando la barca accelera, ruota in avanti e tu cazzi. In una raffica ruota per un attimo verso poppa: di bolina puoi stringere un po’ di più, in poppa poggiare un po’ di più. Più la barca è veloce, più arriva da prua: l’AC75 del gioco, sui suoi foil, naviga a tre volte la velocità del vento, e il suo vento apparente resta a prua anche quando va in poppa.', 'As velas são reguladas pelo vento aparente, então é ele que mexe nas escotas. Quando o barco acelera, ele vai para a proa e você caça. Numa rajada, ele vai para trás por um instante: na orça o barco pode orçar um pouco mais, na popa arribar um pouco mais. Quanto mais rápido o barco, mais de proa ele vem: o AC75 do jogo, nos foils, veleja a três vezes a velocidade do vento, e o vento aparente dele continua de proa mesmo indo em popa.'),
      ], tip: t('The wind in a forecast is the true wind. In the game the sheet’s green band follows the apparent wind; the wind box and the ring round your boat show the true.',
        'В прогнозе — истинный ветер. В игре зелёная полоса на шкоте следует за вымпельным ветром, а окно ветра и кольцо вокруг лодки показывают истинный.', 'El viento de un pronóstico es el viento real. En el juego la banda verde de la escota sigue el viento aparente; el cuadro del viento y el anillo alrededor de tu barco muestran el real.', 'Der Wind in einer Vorhersage ist der wahre Wind. Im Spiel folgt der grüne Bereich der Schot dem scheinbaren Wind; die Windanzeige und der Ring um dein Boot zeigen den wahren.', 'Bir tahmindeki rüzgâr gerçek rüzgârdır. Oyunda iskotanın yeşil bandı görünen rüzgârı izler; rüzgâr kutusu ve teknenin etrafındaki halka gerçeği gösterir.', 'Le vent d’une prévision est le vent réel. Dans le jeu, la bande verte de l’écoute suit le vent apparent ; la case du vent et l’anneau autour de ton bateau montrent le vent réel.', 'Il vento di una previsione è il vento reale. Nel gioco la fascia verde della scotta segue il vento apparente; il riquadro del vento e l’anello intorno alla tua barca mostrano quello reale.', 'O vento de uma previsão é o vento real. No jogo, a faixa verde da escota segue o vento aparente; o quadro do vento e o anel em volta do seu barco mostram o real.') },
      { id: 'fast', h: t('Which point of sail is fastest', 'Какой курс самый быстрый', 'Qué rumbo es el más rápido', 'Welcher Kurs zum Wind am schnellsten ist', 'En hızlı seyir açısı hangisi', 'Quelle allure est la plus rapide', 'Qual è l’andatura più veloce', 'Qual andadura é a mais rápida'), p: [
        t('For most boats it is a reach. With the wind across her, more of the sails’ force drives her forward and less pushes her sideways than close-hauled, and the apparent wind is still strong. A heavy displacement boat is fastest about on the beam; a light one with a gennaker, in a breeze, on a broad reach, where she can plane and surf.',
          'У большинства лодок — галфвинд или бакштаг. Когда ветер дует поперёк, большая часть силы парусов толкает лодку вперёд, а меньшая, чем в бейдевинд, — вбок, и вымпельный ветер всё ещё сильный. Тяжёлая водоизмещающая лодка быстрее всего примерно в галфвинд, а лёгкая, с генакером и в хороший ветер, — в бакштаг, где она может глиссировать и ловить волну.', 'Para la mayoría de los barcos es un través. Con el viento cruzado, más fuerza de las velas lo empuja hacia delante y menos de lado que de ceñida, y el viento aparente sigue siendo fuerte. Un barco pesado de desplazamiento es más rápido hacia el través; uno ligero con gennaker, con brisa, en un largo, donde puede planear y surfear.', 'Für die meisten Boote ist es ein Raumschotskurs. Mit dem Wind quer zum Boot treibt mehr von der Kraft der Segel es nach vorn und weniger drückt es seitwärts als hoch am Wind, und der scheinbare Wind ist immer noch stark. Ein schweres Verdrängerboot ist etwa auf dem Halbwindkurs am schnellsten; ein leichtes mit Gennaker bei Wind auf einem Raumwindkurs, wo es gleiten und surfen kann.', 'Çoğu tekne için apazdır. Rüzgâr enine geldiğinde yelkenlerin kuvvetinin daha fazlası tekneyi ileri sürer ve orsadakinden daha azı yana iter; görünen rüzgâr da hâlâ güçlüdür. Ağır deplasmanlı bir tekne yaklaşık yan apazda en hızlıdır; gennaker’lı hafif bir tekne, esintide, kayabildiği ve sörf yapabildiği geniş apazda.', 'Pour la plupart des bateaux, c’est le largue. Avec le vent de travers, une plus grande part de la force des voiles le pousse vers l’avant et une moindre le pousse de côté qu’au près, et le vent apparent reste fort. Un lourd bateau à déplacement est le plus rapide à peu près au travers ; un bateau léger sous gennaker, dans la brise, au grand largue, où il peut planer et surfer.', 'Per la maggior parte delle barche è il lasco. Con il vento di traverso, rispetto alla bolina stretta una parte maggiore della forza delle vele la spinge in avanti e una minore la spinge di lato, e il vento apparente è ancora forte. Una barca dislocante pesante è più veloce più o meno al traverso; una leggera con il gennaker, con vento teso, al gran lasco, dove può planare e surfare.', 'Para a maioria dos barcos, é o través. Com o vento entrando pelo lado, uma parte maior da força das velas empurra o barco para a frente e uma menor o empurra de lado do que na orça, e o vento aparente continua forte. Um barco pesado de deslocamento é mais rápido mais ou menos no través; um leve com gennaker, com vento forte, no largo, onde ele pode planar e surfar.'),
        t('In the game each yacht sails to her own speeds for every wind and angle. The J Class is fastest on a beam reach; the JPK 1050 with the wind some 110° to 135° off, further aft the harder it blows. For every one of them, the dead run is the slowest way downwind.',
          'В игре у каждой яхты свои скорости для каждого ветра и угла. J Class быстрее всего в галфвинд, JPK 1050 — когда ветер дует под 110–135°, и чем он сильнее, тем ближе к корме. И у всех чистый фордевинд — самый медленный попутный курс.', 'En el juego cada yate navega a sus propias velocidades para cada viento y ángulo. El J Class es más rápido en un través; el JPK 1050 con el viento a unos 110° a 135°, más a popa cuanto más sopla. Para todos ellos, la empopada total es la forma más lenta de ir de popa.', 'Im Spiel segelt jede Yacht nach ihren eigenen Geschwindigkeiten für jeden Wind und Winkel. Die J Class ist auf einem Halbwindkurs am schnellsten; die JPK 1050 mit dem Wind etwa 110° bis 135° von vorn, weiter achtern, je stärker es weht. Für jede von ihnen ist der Vorwindkurs genau vor dem Wind der langsamste Weg nach Lee.', 'Oyunda her yat her rüzgâr ve açı için kendi hızlarında gider. J Class yan apazda en hızlıdır; JPK 1050 rüzgâr yaklaşık 110° ile 135° açıdayken, rüzgâr ne kadar sertse o kadar geriden. Hepsi için tam pupa, rüzgâraltına giden en yavaş yoldur.', 'Dans le jeu, chaque yacht a ses propres vitesses pour chaque force de vent et chaque angle. Le J Class est le plus rapide au travers ; le JPK 1050 avec le vent à quelque 110° à 135°, d’autant plus en arrière qu’il souffle fort. Pour tous, le plein vent arrière est la façon la plus lente de descendre.', 'Nel gioco ogni yacht ha le sue velocità per ogni vento e ogni angolo. Il J Class è più veloce al traverso; il JPK 1050 con il vento tra circa 110° e 135°, tanto più a poppa quanto più soffia forte. Per tutti, la poppa piena è il modo più lento di scendere.', 'No jogo, cada veleiro tem as próprias velocidades para cada vento e cada ângulo. O J Class é mais rápido no través; o JPK 1050, com o vento a uns 110° a 135°, mais para trás quanto mais forte sopra. Para todos eles, a popa rasa é o jeito mais lento de descer.'),
      ], tip: t('Fastest isn’t quickest to the mark. Upwind and downwind what counts is VMG, your speed towards the wind or away from it, and it is best close-hauled and at a downwind angle, not on the reaches between. The game shows your VMG with your speed.',
        'Самый быстрый курс — не самый короткий путь к знаку. На лавировке и на попутном важен VMG — скорость к ветру или от него, — а он лучше всего в бейдевинд и под попутным углом, а не на курсах между ними. Игра показывает VMG рядом со скоростью.', 'Lo más rápido no es lo más pronto a la baliza. De ceñida y de popa lo que cuenta es el VMG, tu velocidad hacia el viento o alejándote de él, y es mejor de ceñida y en un ángulo de popa, no en los través intermedios. El juego muestra tu VMG junto a tu velocidad.', 'Am schnellsten zu fahren heißt nicht, am schnellsten an der Bahnmarke zu sein. Am Wind und vor dem Wind zählt VMG, deine Geschwindigkeit zum Wind hin oder von ihm weg, und sie ist hoch am Wind und in einem Winkel vor dem Wind am besten, nicht auf den Raumschotskursen dazwischen. Das Spiel zeigt dein VMG zusammen mit deiner Geschwindigkeit.', 'En hızlı, şamandıraya en çabuk varan demek değildir. Orsada ve pupada önemli olan VMG’dir, rüzgâra ya da rüzgârdan uzağa doğru hızın; en iyisi orsada ve bir pupa açısındadır, aradaki apazlarda değil. Oyun VMG’ni hızınla birlikte gösterir.', 'Le plus rapide n’est pas le plus court jusqu’à la bouée. Au près comme au portant, ce qui compte, c’est la VMG, ta vitesse vers le vent ou en s’en éloignant, et elle est meilleure au près et à un angle de portant qu’aux largues entre les deux. Le jeu affiche ta VMG à côté de ta vitesse.', 'Più veloce non vuol dire prima alla boa. Di bolina e in poppa conta la VMG, la tua velocità verso il vento o in direzione opposta, ed è migliore di bolina stretta e a un angolo di poppa, non sui laschi in mezzo. Il gioco mostra la VMG insieme alla velocità.', 'O mais veloz não é o que chega primeiro à boia. Na orça e na popa, o que conta é o VMG, a sua velocidade em direção ao vento ou para longe dele, e ele é melhor na orça e num ângulo de popa, não nos traveses entre eles. O jogo mostra o seu VMG junto com a velocidade.') },
    ],
    more: [
      { label: t('Glossary: points of sail and turns', 'Словарь: курсы и повороты', 'Glosario: rumbos y giros', 'Glossar: Kurse zum Wind und Drehungen', 'Sözlük: seyir açıları ve dönüşler', 'Glossaire : allures et manœuvres', 'Glossario: andature e manovre', 'Glossário: andaduras e manobras'), href: '/learn/glossary#close-hauled' },
      { label: t('Sail trim and boat speed', 'Настройка парусов и скорость лодки', 'Trimado y velocidad del barco', 'Segeltrimm und Bootsgeschwindigkeit', 'Yelken trimi ve tekne hızı', 'Réglage des voiles et vitesse', 'Regolazione delle vele e velocità', 'Regulagem das velas e velocidade do barco'), href: '/learn/trim' },
      { label: t('Sailing downwind', 'Попутные курсы', 'Navegar de popa', 'Vor dem Wind segeln', 'Pupada yelken açmak', 'Naviguer au portant', 'Navigare in poppa', 'Velejar em popa'), href: '/learn/downwind' },
    ],
    try: { label: t('Sail a triangle', 'Пройди треугольник', 'Navega un triángulo', 'Ein Dreieck segeln', 'Bir üçgen yelken aç', 'Courir un triangle', 'Corri un triangolo', 'Veleje um triângulo'), href: '/race/free', text: t(
      'Pick the triangle in a custom race: a beat, a tight reach out to the wing mark, a gybe there and a broad reach back — every point of sail in one lap.',
      'Выбери треугольник в своей гонке: лавировка, крутой галфвинд к боковому знаку, там поворот фордевинд и бакштаг обратно — все курсы за один круг.', 'Elige el triángulo en una regata personalizada: una ceñida, un través cerrado hasta la baliza de través, una trasluchada allí y un largo de vuelta — todos los rumbos en una vuelta.', 'Such dir in einer freien Regatta das Dreieck aus: ein Kreuz, ein angeluvter Halbwindkurs zur Raumtonne, dort eine Halse und ein Raumschotskurs zurück — jeder Kurs zum Wind in einer Runde.', 'Serbest yarışta üçgeni seç: bir orsa ayağı, kanat şamandırasına dar apaz, orada bir kavança ve geri geniş apaz, her seyir açısı tek turda.', 'Choisis le triangle dans une régate libre : un bord de près, un largue serré jusqu’à la bouée de largue, un empannage et un grand largue pour revenir — toutes les allures en un tour.', 'Scegli il triangolo in una regata libera: un lato di bolina, un lasco stretto fino alla boa di lasco, lì una strambata e un gran lasco per tornare — tutte le andature in un giro.', 'Escolha o triângulo numa regata livre: uma orça, um través fechado até a boia de través, um jibe ali e um largo de volta — todas as andaduras em uma volta.') },
  };

  return {
    slug,
    title: t('How to tack and gybe a sailboat', 'Как делать поворот оверштаг и фордевинд', 'Cómo virar y trasluchar un velero', 'Wie man ein Segelboot wendet und halst', 'Bir yelkenlide tramola ve kavança nasıl atılır', 'Comment virer de bord et empanner un voilier', 'Come virare e strambare con una barca a vela', 'Como cambar e jibar um veleiro'),
    short: t('Tacking and gybing', 'Оверштаг и фордевинд', 'Virar y trasluchar', 'Wenden und Halsen', 'Tramola ve kavança atmak', 'Virement de bord et empannage', 'Virare e strambare', 'Cambada e jibe'),
    kicker: t('Racing guides · tacking', 'Пособия по гонкам · повороты', 'Guías de regata · virar', 'Regattaleitfäden · Wenden', 'Yarış rehberleri · tramola', 'Guides de régate · virement de bord', 'Guide alla regata · virata', 'Guias de regata · cambada'),
    img: shot('gd-tack-v2', t('Your boat head to wind in the middle of a tack in the game', 'Твоя лодка стоит носом к ветру в середине поворота оверштаг в игре', 'Tu barco proa al viento en mitad de una virada en el juego', 'Dein Boot mit dem Bug im Wind mitten in einer Wende im Spiel', 'Oyunda bir tramolanın ortasında rüzgâra dönük teknen', 'Ton bateau face au vent au milieu d’un virement de bord dans le jeu', 'La tua barca prua al vento a metà di una virata nel gioco', 'Seu barco de proa ao vento no meio de uma cambada no jogo'), 3840, 1600),
    description: t(
      'How to tack and gybe a sailboat step by step: the calls, how far to turn, keeping speed, roll tacks, avoiding a crash gybe, which to choose and rule 13.',
      'Как делать поворот оверштаг и фордевинд шаг за шагом: команды, насколько поворачивать, как не терять ход, ролл-так, самопроизвольный поворот и правило 13.', 'Cómo virar y trasluchar un velero paso a paso: las voces, cuánto girar, mantener la velocidad, viradas rodadas, evitar una trasluchada violenta, cuál elegir y la regla 13.', 'Wie man ein Segelboot wendet und halst, Schritt für Schritt: die Kommandos, wie weit man dreht, Fahrt halten, Rollwenden, die Patenthalse vermeiden, was man wählt und Regel 13.', 'Bir yelkenlide tramola ve kavança adım adım nasıl atılır: komutlar, ne kadar dönmeli, hızı korumak, roll tramola, kaza kavançasından kaçınmak, hangisini seçmeli ve kural 13.', 'Virer de bord et empanner un voilier pas à pas : les annonces, de combien tourner, garder sa vitesse, le virement roulé, éviter l’empannage involontaire, lequel choisir et la règle 13.', 'Come virare e strambare una barca a vela passo per passo: gli ordini, di quanto girare, mantenere la velocità, la virata rollata, evitare la strambata involontaria, quale scegliere e la regola 13.', 'Como cambar e jibar um veleiro passo a passo: os comandos, quanto virar, manter a velocidade, roll tack, evitar o jibe involuntário, qual escolher e a regra 13.'),
    intro: t(
      'A tack turns the bow through the wind, from one tack to the other; a gybe turns the stern through it. Upwind you tack, downwind you gybe. Done well, each costs a little speed. Done badly, a tack leaves you stopped head to wind, and a gybe brings the boom across someone’s head.',
      'При повороте оверштаг через линию ветра проходит нос, и лодка переходит с галса на галс; при повороте фордевинд — корма. На лавировке поворачивают оверштаг, на попутном — фордевинд. Хороший поворот стоит немного скорости. Плохой оверштаг оставляет тебя стоять носом к ветру, а плохой фордевинд проносит гик над чьей-нибудь головой.', 'Una virada gira la proa a través del viento, de una amura a la otra; una trasluchada gira la popa a través de él. De ceñida se vira, de popa se traslucha. Bien hecha, cada una cuesta un poco de velocidad. Mal hecha, una virada te deja parado proa al viento, y una trasluchada trae la botavara a la cabeza de alguien.', 'Eine Wende dreht den Bug durch den Wind, eine Halse das Heck. Am Wind wendest du, vor dem Wind halst du. Gut gemacht kostet jede ein wenig Fahrt. Schlecht gemacht lässt dich eine Wende mit dem Bug im Wind stehen, und eine Halse bringt den Baum jemandem an den Kopf.', 'Tramola pruvayı rüzgârın içinden geçirerek bir kontradan ötekine döner; kavança kıçı geçirir. Orsada tramola atarsın, pupada kavança. İyi yapılırsa her biri biraz hıza mal olur. Kötü yapılırsa tramola seni rüzgâra dönük durmuş bırakır, kavança da bomu birinin başının üzerine getirir.', 'Un virement de bord fait passer l’étrave dans le vent, d’une amure à l’autre ; un empannage y fait passer l’arrière. Au près on vire, au portant on empanne. Bien faits, l’un comme l’autre coûtent un peu de vitesse. Mal faits, un virement te laisse arrêté vent debout, et un empannage envoie la bôme dans la tête de quelqu’un.', 'Una virata porta la prua attraverso il vento, da una mura all’altra; una strambata ci porta la poppa. Di bolina si vira, in poppa si stramba. Fatte bene, costano entrambe un po’ di velocità. Fatte male, una virata ti lascia fermo prua al vento, e una strambata manda il boma in testa a qualcuno.', 'A cambada passa a proa pelo vento, de uma amura para a outra; o jibe passa a popa. Na orça você camba, na popa você jiba. Bem feitos, cada um custa um pouco de velocidade. Mal feitos, a cambada deixa você parado de proa ao vento, e o jibe joga a retranca na cabeça de alguém.'),
    sections: [
      { id: 'tack', h: t('The tack, step by step', 'Оверштаг шаг за шагом', 'La virada, paso a paso', 'Die Wende, Schritt für Schritt', 'Tramola, adım adım', 'Le virement de bord, pas à pas', 'La virata, passo per passo', 'A cambada, passo a passo'), p: [
        t('Look first: clear water on the new tack, no boat you would tack in front of, and full speed, so that she carries her way through the wind. Call “Ready about” and wait for the crew’s “Ready”: the old jib sheet in hand, the new one ready.',
          'Сначала осмотрись: вода на новом галсе свободна, нет лодки, перед которой ты повернёшь, и ход полный, чтобы инерции хватило пройти линию ветра. Командуй «К повороту оверштаг!» и дождись ответа «Готов!»: рабочий шкот стакселя в руках, новый наготове.', 'Mira primero: agua libre en la nueva amura, ningún barco por cuya proa fueras a virar, y a toda velocidad, para que pase el viento con su arrancada. Canta “Listos para virar” y espera el “Listo” de la tripulación: la escota vieja del foque en la mano, la nueva preparada.', 'Schau zuerst: klares Wasser auf dem neuen Bug, kein Boot, vor dem du wenden würdest, und volle Fahrt, damit das Boot mit Schwung durch den Wind kommt. Ruf „Klar zur Wende“ und warte auf das „Klar“ der Crew: die alte Fockschot in der Hand, die neue bereit.', 'Önce bak: yeni kontrada açık su, önünden tramola atacağın bir tekne yok ve tam hız, böylece tekne rüzgârın içinden yolunu taşır. “Tramolaya hazır” de ve mürettebatın “Hazır” demesini bekle: eski flok iskotası elde, yenisi hazır.', 'Regarde d’abord : de l’eau libre sur la nouvelle amure, aucun bateau devant lequel tu virerais, et pleine vitesse, pour que le bateau garde son erre en passant le vent. Annonce « Paré à virer » et attends le « Paré » de l’équipier : l’ancienne écoute de foc en main, la nouvelle prête.', 'Prima guarda: acqua libera sulle nuove mure, nessuna barca davanti a cui viresti, e piena velocità, così che la barca conservi l’abbrivio attraverso il vento. Chiama «Pronti a virare» e aspetta il «Pronti» dell’equipaggio: la vecchia scotta del fiocco in mano, la nuova pronta.', 'Olhe primeiro: água livre na nova amura, nenhum barco na frente do qual você cambaria, e velocidade máxima, para o barco manter o seguimento ao passar pelo vento. Chame “Preparar para cambar” e espere o “Pronto” da tripulação: a escota velha da buja na mão, a nova pronta.'),
        t('Call “Lee-oh” and put the helm over smoothly: a tiller pushed towards the sail, a wheel turned the way the bow is to go. As the jib starts to back, let its old sheet go and pull it in fast on the new side; the main comes across by itself. Straighten the helm as she comes onto close-hauled on the new tack. Then trim: the sheets a touch eased until she picks up speed, in hard once she has.',
          'Командуй «Поворот!» и плавно переложи руль: румпель — к парусу, штурвал — в ту сторону, куда должен пойти нос. Когда стаксель начнёт обстеняться, отдай старый шкот и быстро выбери новый; грот перейдёт сам. Выпрями руль, когда лодка ляжет в бейдевинд на новом галсе. Потом настрой паруса: шкоты чуть потравлены, пока лодка разгоняется, и выбраны туго, когда разогналась.', 'Canta “¡Virando!” y mete el timón con suavidad: una caña empujada hacia la vela, una rueda girada hacia donde ha de ir la proa. Cuando el foque empiece a hacer contra, suelta su escota vieja y cázalo rápido por el otro lado; la mayor pasa sola. Endereza el timón cuando entre de ceñida en la nueva amura. Luego trimado: las escotas un poco sueltas hasta que gane velocidad, cazadas a fondo cuando la tenga.', 'Ruf „Re“ und leg das Ruder weich um: eine Pinne zum Segel hin geschoben, ein Rad in die Richtung gedreht, in die der Bug soll. Sobald die Fock back steht, lass ihre alte Schot los und hol sie schnell auf der neuen Seite dicht; das Groß kommt von allein hinüber. Richte das Ruder gerade, wenn das Boot auf dem neuen Bug hoch am Wind liegt. Dann trimme: die Schoten etwas gefiert, bis es Fahrt aufnimmt, hart dicht, sobald es sie hat.', '“Lee-oh” de ve dümeni yumuşakça yatır: yelkene doğru itilen bir yekeme, pruvanın gideceği yöne çevrilen bir dümen simidi. Flok geri vurmaya başlayınca eski iskotasını bırak ve yeni yanda hızla çek; ana kendiliğinden geçer. Tekne yeni kontrada orsaya gelirken dümeni düzelt. Sonra trim et: hız toplayana kadar iskotalar biraz gevşek, topladıktan sonra sonuna kadar çekili.', 'Annonce « Envoyez » et mets la barre doucement : la barre franche poussée vers la voile, la roue tournée du côté où doit aller l’étrave. Quand le foc commence à prendre à contre, largue l’ancienne écoute et borde vite sur le nouveau bord ; la grand-voile passe toute seule. Redresse la barre quand le bateau arrive au près sur la nouvelle amure. Puis règle : les écoutes un poil choquées jusqu’à ce qu’il reprenne de la vitesse, bordées à fond une fois qu’il l’a.', 'Chiama «Viro» e porta il timone con decisione ma senza strappi: la barra spinta verso la vela, la ruota girata dalla parte in cui deve andare la prua. Quando il fiocco comincia a prendere a collo, molla la vecchia scotta e cazza veloce sul nuovo lato; la randa passa da sola. Raddrizza il timone quando la barca arriva di bolina stretta sulle nuove mure. Poi regola: scotte un filo lascate finché non riprende velocità, cazzate a fondo una volta ripresa.', 'Chame “Cambando” e mova o leme com suavidade: a cana empurrada em direção à vela, a roda girada para o lado em que a proa deve ir. Quando a buja começar a encher ao contrário, solte a escota velha e cace rápido do novo lado; a vela grande cruza sozinha. Endireite o leme quando o barco chegar à orça na nova amura. Depois regule: as escotas um pouco folgadas até ele ganhar velocidade, bem caçadas quando ganhar.'),
      ], tip: t('In the game, Tack — the button, or Space on a keyboard — does all of it: she turns to the same angle to the wind on the other tack and the crew calls it. Tacking by hand with the steering works too.',
        'В игре «Поворот» — кнопка или пробел на клавиатуре — делает всё это сам: лодка поворачивает на тот же угол к ветру на другом галсе, а команда даёт команды. Можно повернуть и рулём, вручную.', 'En el juego, Virar — el botón, o Espacio en un teclado — lo hace todo: gira al mismo ángulo con el viento en la otra amura y la tripulación lo canta. Virar a mano con el timón también vale.', 'Im Spiel macht Wende — der Knopf oder die Leertaste auf einer Tastatur — alles: Das Boot dreht auf denselben Winkel zum Wind auf dem anderen Bug, und die Crew ruft es aus. Von Hand mit der Steuerung zu wenden geht auch.', 'Oyunda Tramola, yani düğme ya da klavyede Boşluk, hepsini yapar: tekne öbür kontrada rüzgâra aynı açıya döner ve mürettebat komutu verir. Dümenle elle tramola atmak da olur.', 'Dans le jeu, Virer — le bouton, ou Espace sur un clavier — fait tout : le bateau tourne jusqu’au même angle au vent sur l’autre amure et l’équipage l’annonce. Virer à la main, à la barre, marche aussi.', 'Nel gioco, Vira — il pulsante, o Spazio sulla tastiera — fa tutto: la barca gira fino allo stesso angolo rispetto al vento sulle altre mure e l’equipaggio dà l’ordine. Funziona anche virare a mano con il timone.', 'No jogo, Cambar — o botão, ou Espaço no teclado — faz tudo isso: o barco vira até o mesmo ângulo em relação ao vento na outra amura e a tripulação anuncia. Cambar à mão, no leme, também funciona.') },
      { id: 'turn', h: t('How far, and keeping speed', 'Насколько поворачивать и как не терять ход', 'Cuánto, y mantener la velocidad', 'Wie weit, und Fahrt halten', 'Ne kadar ve hızı korumak', 'De combien tourner, et garder sa vitesse', 'Di quanto girare, e mantenere la velocità', 'Quanto virar, e manter a velocidade'), p: [
        t('From close-hauled to close-hauled most boats turn through about 80° to 90°, twice their angle to the wind. Turn too slowly and she loses her way before the bow is through, and stops head to wind, in irons. Turn too hard and the rudder, across the flow, brakes her. A smooth, steady turn loses least; in waves, tack on a flat patch.',
          'Из бейдевинда в бейдевинд большинство лодок поворачивают примерно на 80–90° — на свой двойной угол к ветру. Повернёшь слишком медленно — лодка потеряет ход раньше, чем нос пройдёт ветер, и встанет в левентик. Слишком резко — руль поперёк потока затормозит её. Меньше всего теряет плавный, ровный поворот; в волну поворачивай на участке поглаже.', 'De ceñida a ceñida la mayoría de los barcos giran unos 80° a 90°, el doble de su ángulo con el viento. Si giras demasiado despacio pierde la arrancada antes de pasar la proa, y se para proa al viento. Si giras demasiado fuerte, el timón, cruzado a la corriente, la frena. Un giro suave y constante pierde menos; con olas, vira en un trozo plano.', 'Von hoch am Wind zu hoch am Wind drehen die meisten Boote um etwa 80° bis 90°, das Doppelte ihres Winkels zum Wind. Drehst du zu langsam, verliert es den Schwung, bevor der Bug durch ist, und bleibt im Wind stehen. Drehst du zu hart, bremst das Ruder quer zur Strömung. Eine weiche, gleichmäßige Drehung verliert am wenigsten; bei Wellen wende auf einem glatten Fleck.', 'Orsadan orsaya çoğu tekne yaklaşık 80° ile 90° döner, rüzgâra açısının iki katı. Çok yavaş dönersen pruva geçmeden yolunu kaybeder ve rüzgâra dönük durup rüzgâra dikilir. Çok sert dönersen akıma enine duran dümen onu frenler. Yumuşak, düzenli bir dönüş en az kaybettirir; dalgada düz bir yerde tramola at.', 'D’un près à l’autre, la plupart des bateaux tournent d’environ 80° à 90°, deux fois leur angle au vent. Tourne trop lentement et le bateau perd son erre avant que l’étrave soit passée, et il s’arrête vent debout. Tourne trop fort et le safran, en travers de l’écoulement, le freine. Un virement souple et régulier perd le moins ; dans les vagues, vire sur une zone plate.', 'Da bolina stretta a bolina stretta la maggior parte delle barche gira di circa 80°–90°, il doppio del loro angolo rispetto al vento. Gira troppo piano e la barca perde l’abbrivio prima che la prua sia passata, e si ferma prua al vento, nell’angolo morto. Gira troppo forte e il timone, di traverso al flusso, la frena. Una virata fluida e costante perde meno di tutte; con l’onda, vira in un tratto di acqua piatta.', 'De orça a orça, a maioria dos barcos vira uns 80° a 90°, o dobro do ângulo deles em relação ao vento. Vire devagar demais e o barco perde o seguimento antes de a proa passar, e para de proa ao vento, aproado. Vire forte demais e o leme, atravessado no fluxo, freia o barco. Uma virada suave e constante perde menos; com ondas, cambe num trecho liso.'),
        t('Every tack costs speed, and building it again takes a while: longer in light air and in a heavy boat. Come out a few degrees below close-hauled with the sheets a little eased, let her accelerate, then head up to her proper angle. In light air, tack less.',
          'Каждый поворот стоит скорости, и набрать её снова удаётся не сразу: дольше в слабый ветер и на тяжёлой лодке. Выходи из поворота на несколько градусов ниже бейдевинда с чуть потравленными шкотами, дай лодке разогнаться и потом приведись до её угла. В слабый ветер поворачивай реже.', 'Cada virada cuesta velocidad, y recuperarla lleva un rato: más con poco viento y en un barco pesado. Sal unos grados por debajo de la ceñida con las escotas algo sueltas, deja que acelere y luego orza hasta su ángulo debido. Con poco viento, vira menos.', 'Jede Wende kostet Fahrt, und sie wieder aufzubauen dauert eine Weile: länger bei Leichtwind und in einem schweren Boot. Komm ein paar Grad unter hoch am Wind heraus, mit etwas gefierten Schoten, lass es beschleunigen und luv dann auf seinen richtigen Winkel an. Bei Leichtwind wende weniger.', 'Her tramola hıza mal olur ve onu yeniden toplamak biraz sürer: hafif rüzgârda ve ağır teknede daha uzun. Orsanın birkaç derece altında, iskotalar biraz gevşek çık, hızlanmasına izin ver, sonra uygun açısına orsala. Hafif rüzgârda daha az tramola at.', 'Chaque virement coûte de la vitesse, et la reprendre demande un moment : plus longtemps par petit temps et sur un bateau lourd. Sors quelques degrés sous le près, les écoutes un peu choquées, laisse le bateau accélérer, puis remonte à son bon angle. Par petit temps, vire moins.', 'Ogni virata costa velocità, e riprenderla richiede un po’: di più con poco vento e su una barca pesante. Esci qualche grado sotto la bolina stretta con le scotte un po’ lascate, lascia accelerare la barca, poi orza fino al suo angolo giusto. Con poco vento, vira meno.', 'Toda cambada custa velocidade, e recuperá-la leva um tempo: mais com vento fraco e num barco pesado. Saia alguns graus abaixo da orça com as escotas um pouco folgadas, deixe o barco acelerar e então orce até o ângulo certo. Com vento fraco, cambe menos.'),
        t('Dinghy sailors roll tack: they heel her to windward as she turns, which helps her round, then cross and flatten her hard on the new side, which flicks the sail and gets her going. Rule 42 allows it, as long as she comes out no faster than she would have been without the tack.',
          'На швертботах делают поворот с раскачкой — ролл-так: в повороте кренят лодку на ветер, что помогает ей повернуть, а потом переходят на новый борт и резко её выравнивают, и этот рывок парусом разгоняет лодку. Правило 42 это разрешает, если после поворота лодка идёт не быстрее, чем шла бы без него.', 'Los regatistas de deriva hacen la virada rodada: escoran el barco a barlovento al girar, lo que ayuda a pasar, y luego cruzan y la aplanan con fuerza en el nuevo lado, lo que sacude la vela y la pone en marcha. La regla 42 lo permite, siempre que salga a no más velocidad de la que habría tenido sin la virada.', 'Jollensegler wenden mit Rolle: Sie legen das Boot beim Drehen nach Luv über, was ihm hilft, herumzukommen, dann gehen sie hinüber und richten es auf der neuen Seite hart auf, was das Segel anstößt und es in Fahrt bringt. Regel 42 erlaubt es, solange es nicht schneller herauskommt, als es ohne die Wende gewesen wäre.', 'Dinghy yelkencileri roll tramola atar: tekne dönerken onu rüzgâra yatırırlar, bu dönmesine yardım eder, sonra karşıya geçip yeni yanda sertçe düzleştirirler; bu yelkeni sallar ve tekneyi hızlandırır. Kural 42 buna izin verir, tekne tramola olmasaydı olacağından daha hızlı çıkmadığı sürece.', 'Les dériveurs font des virements roulés : ils gîtent le bateau au vent pendant qu’il tourne, ce qui l’aide à pivoter, puis passent de l’autre côté et le remettent à plat d’un coup sur le nouveau bord, ce qui fait claquer la voile et le relance. La règle 42 l’autorise, tant qu’il n’en sort pas plus vite qu’il ne l’aurait été sans le virement.', 'I derivisti fanno la virata rollata: sbandano la barca sopravvento mentre gira, il che la aiuta a girare, poi passano dall’altra parte e la raddrizzano di colpo sul nuovo lato, il che fa sventolare la vela e la rilancia. La regola 42 lo permette, purché la barca non esca dalla virata più veloce di quanto sarebbe stata senza.', 'Velejadores de dingue fazem roll tack: adernam o barco para barlavento enquanto ele vira, o que ajuda a girar, e então passam para o outro lado e o endireitam com força no novo bordo, o que abana a vela e faz o barco andar. A regra 42 permite, desde que ele não saia mais rápido do que estaria sem a cambada.'),
      ], tip: t('There is no roll tack in the game. The Laser and the Optimist stop in a tack and go again at once; the J Class takes some three times as long as the JPK 1050. Come out of a tack slow and the game tells you to foot.',
        'В игре ролл-така нет. Laser и Optimist в повороте останавливаются и сразу идут дальше; J Class поворачивает примерно втрое дольше JPK 1050. Вышел из поворота без скорости — игра подскажет увалиться и разогнаться.', 'En el juego no hay virada rodada. El Laser y el Optimist se paran en la virada y arrancan de nuevo enseguida; el J Class tarda unas tres veces más que el JPK 1050. Sal lento de una virada y el juego te dice que arribes.', 'Im Spiel gibt es keine Rollwende. Der Laser und der Optimist bleiben in der Wende stehen und fahren sofort wieder los; die J Class braucht etwa dreimal so lang wie die JPK 1050. Kommst du langsam aus einer Wende, sagt dir das Spiel, du sollst abfallen.', 'Oyunda roll tramola yok. Laser ve Optimist tramolada durup hemen yeniden gider; J Class, JPK 1050’den yaklaşık üç kat uzun sürer. Tramoladan yavaş çıkarsan oyun sana boşlamanı söyler.', 'Il n’y a pas de virement roulé dans le jeu. Le Laser et l’Optimist s’arrêtent dans un virement et repartent aussitôt ; le J Class met environ trois fois plus de temps que le JPK 1050. Sors d’un virement trop lentement et le jeu te dit d’abattre pour relancer.', 'Nel gioco non c’è la virata rollata. Il Laser e l’Optimist si fermano in virata e ripartono subito; il J Class ci mette circa tre volte quanto il JPK 1050. Esci lento da una virata e il gioco ti dice di poggiare per prendere velocità.', 'Não há roll tack no jogo. O Laser e o Optimist param numa cambada e saem andando na hora; o J Class leva umas três vezes mais que o JPK 1050. Saia lento de uma cambada e o jogo manda você arribar para ganhar velocidade.') },
      { id: 'gybe', h: t('The gybe, step by step', 'Фордевинд шаг за шагом', 'La trasluchada, paso a paso', 'Die Halse, Schritt für Schritt', 'Kavança, adım adım', 'L’empannage, pas à pas', 'La strambata, passo per passo', 'O jibe, passo a passo'), p: [
        t('Look first: clear water on the new gybe, and every head clear of the boom’s path. Call “Stand by to gybe”; on a keelboat the crew pull the main in towards the middle, so the boom has less far to swing.',
          'Сначала осмотрись: свободна ли вода на новом галсе и нет ли чьей-нибудь головы на пути гика. Командуй «К повороту фордевинд!»; на килевой лодке команда выбирает грот ближе к середине, чтобы гику было меньше лететь.', 'Mira primero: agua libre en la nueva amura, y todas las cabezas fuera del recorrido de la botavara. Canta “Preparados para trasluchar”; en una quilla la tripulación caza la mayor hacia el centro, para que la botavara tenga menos que recorrer.', 'Schau zuerst: klares Wasser auf der neuen Halse und jeder Kopf frei vom Weg des Baumes. Ruf „Klar zur Halse“; auf einem Kielboot holt die Crew das Groß zur Mitte hin dicht, damit der Baum weniger weit schwingen muss.', 'Önce bak: yeni kavançada açık su ve bomun yolunda kimsenin başı yok. “Kavançaya hazır” de; omurgalıda mürettebat anayı ortaya doğru çeker, böylece bomun savrulacağı mesafe kısalır.', 'Regarde d’abord : de l’eau libre sur la nouvelle amure, et toutes les têtes hors de la trajectoire de la bôme. Annonce « Paré à empanner » ; sur un quillard, l’équipage borde la grand-voile vers l’axe, pour que la bôme ait moins de chemin à faire.', 'Prima guarda: acqua libera sulle nuove mure, e tutte le teste fuori dalla traiettoria del boma. Chiama «Pronti a strambare»; su una barca a chiglia l’equipaggio cazza la randa verso il centro, così il boma ha meno strada da fare.', 'Olhe primeiro: água livre no novo bordo, e todas as cabeças fora do caminho da retranca. Chame “Preparar para jibar”; num barco de quilha, a tripulação caça a vela grande para o centro, para a retranca ter menos caminho a percorrer.'),
        t('Call “Gybe-oh” and bear away steadily. As the stern passes through the wind the boom comes across — in a dinghy, help it with a tug on the mainsheet — and everyone ducks. The moment it crosses, meet her with the helm: with the main filling on the new side she wants to round up. Let the main out on the new side, bring the jib across, and settle on the new course.',
          'Командуй «Поворот!» и ровно уваливайся. Когда корма проходит линию ветра, гик перелетает — на швертботе помоги ему, дёрнув гика-шкот, — и все пригибаются. Как только он перешёл, одерживай рулём: грот наполняется на новом борту, и лодка стремится привестись. Потрави грот на новом борту, перекинь стаксель и ложись на новый курс.', 'Canta “¡Trasluchando!” y arriba con firmeza. Cuando la popa pasa por el viento la botavara cruza — en una deriva, ayúdala con un tirón de la escota de la mayor — y todos se agachan. En cuanto cruza, sal a su encuentro con el timón: con la mayor llenándose en el nuevo lado quiere orzar. Suelta la mayor en el nuevo lado, pasa el foque y asienta el nuevo rumbo.', 'Ruf „Halse“ und fall gleichmäßig ab. Wenn das Heck durch den Wind geht, kommt der Baum hinüber — in einer Jolle hilf ihm mit einem Ruck an der Großschot — und alle ducken sich. In dem Moment, in dem er hinüberkommt, fang das Boot mit dem Ruder ab: Mit dem Groß, das auf der neuen Seite füllt, will es anluven. Fiere das Groß auf der neuen Seite, hol die Fock hinüber und geh auf den neuen Kurs.', '“Gybe-oh” de ve düzenli boşla. Kıç rüzgârın içinden geçerken bom öbür yana gelir; dinghy’de ana iskotasına bir asılmayla ona yardım et; herkes eğilir. Geçtiği anda dümenle karşıla: ana yeni yanda dolarken tekne orsalamak ister. Ananı yeni yanda bırak, floku karşıya getir ve yeni rotaya otur.', 'Annonce « Empannez » et abats régulièrement. Quand l’arrière passe le vent, la bôme passe — en dériveur, aide-la d’un coup sur l’écoute de grand-voile — et tout le monde baisse la tête. Dès qu’elle passe, contre à la barre : avec la grand-voile qui se remplit sur le nouveau bord, le bateau veut partir au lof. Choque la grand-voile sur le nouveau bord, passe le foc et installe-toi sur la nouvelle route.', 'Chiama «Strambo» e poggia con costanza. Quando la poppa passa attraverso il vento il boma passa dall’altra parte — in deriva aiutalo con uno strattone alla scotta della randa — e tutti abbassano la testa. Appena passa, contrasta con il timone: con la randa che si riempie sul nuovo lato la barca vuole orzare. Lasca la randa sul nuovo lato, passa il fiocco e assestati sulla nuova rotta.', 'Chame “Jibando” e arribe de forma constante. Quando a popa passa pelo vento, a retranca cruza — num dingue, ajude com um puxão na escota da vela grande — e todo mundo abaixa a cabeça. Assim que ela cruzar, segure o barco com o leme: com a vela grande enchendo no novo lado, ele quer orçar de repente. Folgue a vela grande no novo lado, passe a buja e firme no novo rumo.'),
      ], tip: t('In the game the same button gybes once the wind is more than about 95° off the bow, and then reads Gybe. Steer through dead downwind by hand instead, turning steadily, and the crew brings the boom across as you go.',
        'В игре та же кнопка делает фордевинд, когда ветер дует больше чем на 95° от носа, и тогда на ней написано «Фордевинд». Можно и вручную: уваливайся через чистый фордевинд ровно, не останавливаясь, и команда перекинет гик по ходу.', 'En el juego el mismo botón traslucha cuando el viento está a más de unos 95° de la proa, y entonces dice Trasluchar. Si en cambio pasas por la popa total a mano, girando con suavidad, la tripulación pasa la botavara mientras lo haces.', 'Im Spiel halst derselbe Knopf, sobald der Wind mehr als etwa 95° vom Bug kommt, und zeigt dann Halse. Steuere stattdessen von Hand durch den Vorwindkurs, gleichmäßig drehend, und die Crew bringt den Baum hinüber, während du fährst.', 'Oyunda aynı düğme, rüzgâr pruvadan yaklaşık 95°’den fazla geldiğinde kavança atar ve o zaman Kavança yazar. Bunun yerine tam pupadan elle, düzenli dönerek geç; mürettebat sen giderken bomu getirir.', 'Dans le jeu, le même bouton empanne dès que le vent est à plus d’environ 95° de l’étrave, et affiche alors Empanner. Ou passe le plein vent arrière à la main, en tournant régulièrement, et l’équipage fait passer la bôme pendant que tu tournes.', 'Nel gioco lo stesso pulsante stramba quando il vento è a più di circa 95° dalla prua, e allora dice Stramba. Oppure passa la poppa piena a mano, girando con costanza, e l’equipaggio porta il boma dall’altra parte mentre giri.', 'No jogo, o mesmo botão jiba quando o vento passa de uns 95° da proa, e então mostra Jibar. Ou passe pela popa rasa à mão, virando de forma constante, e a tripulação cruza a retranca enquanto você vira.') },
      { id: 'crash', h: t('Avoid the crash gybe', 'Не допусти самопроизвольного поворота', 'Evita la trasluchada violenta', 'Die Patenthalse vermeiden', 'Kaza kavançasından kaçın', 'Éviter l’empannage involontaire', 'Evita la strambata involontaria', 'Evite o jibe involuntário'), p: [
        t('A crash gybe is one you didn’t mean. Sailing by the lee, past dead downwind, the wind gets behind the main and throws the boom across at full speed. It can hurt anyone in its way and break gear, and in a breeze it lays the boat over and spins her round.',
          'Самопроизвольный поворот — это фордевинд, которого ты не хотел. Когда увалился дальше чистого фордевинда, ветер заходит за грот и со всей силы перебрасывает гик. Он может покалечить того, кто на пути, и сломать снаряжение, а в свежий ветер кладёт лодку на борт и разворачивает её.', 'Una trasluchada violenta es la que no querías. Navegando por la contra, más allá de la popa total, el viento entra por detrás de la mayor y lanza la botavara a toda velocidad. Puede herir a quien esté en medio y romper material, y con brisa tumba el barco y lo hace girar sobre sí mismo.', 'Eine Patenthalse ist eine, die du nicht gewollt hast. Segelst du „by the lee“, über den Vorwindkurs hinaus, kommt der Wind hinter das Groß und wirft den Baum mit voller Wucht hinüber. Er kann jeden verletzen, der im Weg ist, und Ausrüstung zerbrechen, und bei Wind legt er das Boot um und dreht es herum.', 'Kaza kavançası, istemediğin kavançadır. Lee’den, tam pupanın ötesinde yelken açarken rüzgâr ananın arkasına geçer ve bomu tam hızla karşıya fırlatır. Yoluna çıkanı yaralayabilir ve donanımı kırabilir, rüzgârda da tekneyi yatırıp çevirir.', 'Un empannage involontaire, c’est celui que tu n’as pas voulu. Sur la panne, au-delà du plein vent arrière, le vent passe derrière la grand-voile et envoie la bôme de l’autre côté à pleine vitesse. Il peut blesser quiconque se trouve sur sa trajectoire et casser du matériel, et dans la brise il couche le bateau et le fait partir au lof.', 'Una strambata involontaria è quella che non volevi. Alla strapoggia, oltre la poppa piena, il vento passa dietro la randa e scaraventa il boma dall’altra parte a tutta velocità. Può ferire chiunque si trovi sulla sua strada e rompere l’attrezzatura, e con vento teso sdraia la barca e la fa girare.', 'O jibe involuntário é o que você não quis fazer. Navegando de popa rasa, além da popa reta, o vento passa por trás da vela grande e joga a retranca para o outro lado com toda a força. Ela pode machucar quem estiver no caminho e quebrar equipamento, e com vento forte deita o barco e o faz girar.'),
        t('The warnings come first: the jib goes limp and floats across, the wind indicator at the masthead points to the boom’s side, the boom starts to lift. Head up a few degrees and they stop. Keep the kicker on to hold the boom down, and on a cruiser rig a preventer for a long run.',
          'Сначала будут предупреждения: стаксель обвисает и перетягивает на другой борт, флюгер на топе мачты показывает в сторону гика, гик начинает задираться. Приведись на несколько градусов — и всё прекратится. Держи оттяжку гика выбранной, чтобы гик не задирался, а на крейсерской яхте на долгом фордевинде ставь превентер.', 'Antes hay avisos: el foque se afloja y flota de lado, la veleta del tope señala hacia el lado de la botavara, la botavara empieza a subir. Orza unos grados y paran. Mantén la contra puesta para sujetar la botavara hacia abajo, y en un aparejo de crucero una retenida para una empopada larga.', 'Die Warnungen kommen zuerst: Die Fock fällt in sich zusammen und schwingt hinüber, der Verklicker im Masttop zeigt zur Seite des Baumes, der Baum beginnt sich zu heben. Luv ein paar Grad an, und sie hören auf. Lass den Baumniederholer dicht, um den Baum unten zu halten, und auf einer Fahrtenyacht einen Bullenstander für einen langen Vorwindkurs.', 'Uyarılar önce gelir: flok gevşer ve karşıya yüzer, direk başındaki rüzgâr göstergesi bomun yanını gösterir, bom kalkmaya başlar. Birkaç derece orsala, durur. Bomu aşağıda tutmak için bom vincini takılı bırak, gezi teknesi armında uzun pupada bir de preventer kullan.', 'Les signes arrivent d’abord : le foc pend et passe de l’autre côté, la girouette en tête de mât pointe du côté de la bôme, la bôme commence à se soulever. Lofe de quelques degrés et ils disparaissent. Garde le hale-bas bien tendu pour tenir la bôme basse, et sur un croiseur, une retenue de bôme pour un long bord de vent arrière.', 'Prima arrivano i segnali: il fiocco si affloscia e passa dall’altra parte, il segnavento in testa d’albero punta dal lato del boma, il boma comincia ad alzarsi. Orza di qualche grado e spariscono. Tieni il vang cazzato per tenere giù il boma, e su una barca da crociera una ritenuta del boma per una lunga poppa.', 'Os avisos vêm antes: a buja murcha e flutua para o outro lado, a biruta no topo do mastro aponta para o lado da retranca, a retranca começa a subir. Orce alguns graus e eles param. Mantenha o burro caçado para segurar a retranca embaixo e, num barco de cruzeiro, uma retenida na retranca para uma popa longa.'),
      ], tip: t('The game warns you, “By the lee”, with the degrees. Drift on by the lee without turning and the boom comes across on its own: in a breeze she heels hard and slows, and with the gennaker up she can roll and round up.',
        'Игра предупреждает: «Увалился дальше фордевинда» — и на сколько градусов. Если идти так и дальше, не поворачивая, гик перебросит сам: в свежий ветер лодку сильно положит и затормозит, а с генакером её может положить и привести.', 'El juego te avisa, “Por la contra”, con los grados. Si sigues por la contra sin girar, la botavara cruza sola: con brisa escora fuerte y se frena, y con el gennaker izado puede tumbarse y atravesarse.', 'Das Spiel warnt dich, „By the lee“, mit den Graden. Treibst du „by the lee“ weiter, ohne zu drehen, kommt der Baum von allein hinüber: Bei Wind krängt das Boot stark und wird langsamer, und mit gesetztem Gennaker kann es rollen und anluven.', 'Oyun seni “By the lee” diye, dereceleriyle uyarır. Dönmeden lee’den sürüklenmeye devam edersen bom kendiliğinden karşıya gelir: rüzgârda tekne sert yatar ve yavaşlar, gennaker açıkken yuvarlanıp savrulabilir.', 'Le jeu te prévient, « Sur la panne », avec les degrés. Continue à dériver sur la panne sans tourner et la bôme passe toute seule : dans la brise, le bateau gîte fort et ralentit, et sous gennaker il peut rouler et partir au lof.', 'Il gioco ti avvisa, «Alla strapoggia», con i gradi. Continua alla strapoggia senza girare e il boma passa da solo: con vento teso la barca sbanda forte e rallenta, e con il gennaker issato può rollare e straorzare.', 'O jogo avisa, “Popa rasa”, com os graus. Continue de popa rasa sem virar e a retranca cruza sozinha: com vento forte o barco aderna muito e perde velocidade, e com o gennaker içado ele pode rolar e orçar de repente.') },
      { id: 'which', h: t('Tack or gybe?', 'Оверштаг или фордевинд?', '¿Virar o trasluchar?', 'Wenden oder halsen?', 'Tramola mı kavança mı?', 'Virer ou empanner ?', 'Virare o strambare?', 'Cambar ou jibar?'), p: [
        t('Upwind, tack: to gybe from close-hauled you bear away through a run and come all the way back up, some 270° of turning and a lot of ground lost to leeward. Downwind, gybe, for the same reason the other way round. On a reach either will do: tack from a close or a beam reach, gybe from a broad one.',
          'На лавировке поворачивай оверштаг: чтобы сделать фордевинд из бейдевинда, надо увалиться через фордевинд и привестись обратно — около 270° поворота и много потерянного под ветер расстояния. На попутном курсе делай фордевинд — по той же причине, только наоборот. На галфвинде годится любой: из полного бейдевинда или галфвинда поворачивай оверштаг, из бакштага — фордевинд.', 'De ceñida, vira: para trasluchar desde la ceñida arribas por una empopada y vuelves del todo hacia arriba, unos 270° de giro y mucho terreno perdido a sotavento. De popa, traslucha, por la misma razón al revés. En un través sirve cualquiera: vira desde una ceñida holgada o un través, traslucha desde un largo.', 'Am Wind wende: Um von hoch am Wind zu halsen, fällst du durch einen Vorwindkurs ab und kommst den ganzen Weg wieder hoch, etwa 270° Drehung und viel Boden in Lee verloren. Vor dem Wind halse, aus demselben Grund andersherum. Auf einem Raumschotskurs geht beides: Wende von einem angeluvten oder einem Halbwindkurs, halse von einem Raumwindkurs.', 'Orsada tramola at: orsadan kavança atmak için pupadan geçene kadar boşlayıp sonra tamamen geri orsalamak gerekir, yaklaşık 270° dönüş ve rüzgâraltına çok yol kaybı. Pupada kavança at, aynı nedenle tersi. Apazda ikisi de olur: dar ya da yan apazdan tramola, geniş apazdan kavança.', 'Au près, vire : pour empanner depuis le près, tu abats jusqu’au vent arrière et tu remontes jusqu’au bout, quelque 270° de rotation et beaucoup de terrain perdu sous le vent. Au portant, empanne, pour la même raison à l’envers. Au largue, l’un ou l’autre convient : vire depuis le bon plein ou le travers, empanne depuis le grand largue.', 'Di bolina, vira: per strambare dalla bolina stretta poggi fino alla poppa e poi risali fino in fondo, circa 270° di rotazione e molto terreno perso sottovento. In poppa, stramba, per la stessa ragione al contrario. Al lasco va bene l’una o l’altra: vira dalla bolina larga o dal traverso, stramba dal gran lasco.', 'Na orça, cambe: para jibar a partir da orça, você arriba passando pela popa e volta até em cima, uns 270° de giro e muito terreno perdido para sotavento. Na popa, jibe, pelo mesmo motivo ao contrário. No través, qualquer um serve: cambe a partir de uma bolina folgada ou de um través, jibe a partir de um largo.'),
        t('A tack is the gentler of the two, the boom crossing slowly with the sails flapping. In a blow, or with a new crew, turning the long way round through a tack — a “chicken gybe” — costs distance, not gear.',
          'Оверштаг мягче: гик переходит медленно, паруса полощут. В сильный ветер или с новой командой повернуть длинным путём, через оверштаг, стоит расстояния, а не снаряжения.', 'La virada es la más suave de las dos, con la botavara cruzando despacio y las velas aleteando. Con viento fuerte, o con una tripulación nueva, girar por el camino largo a través de una virada — una “trasluchada de gallina” — cuesta distancia, no material.', 'Eine Wende ist die sanftere von beiden, der Baum kommt langsam hinüber, die Segel flattern. Bei Starkwind oder mit einer neuen Crew kostet das lange Herumdrehen durch eine Wende — eine „Angsthalse“ — Strecke, nicht Ausrüstung.', 'Tramola ikisinin yumuşak olanıdır, bom yavaşça geçer ve yelkenler çırpınır. Sert rüzgârda ya da yeni bir mürettebatla tramola üzerinden uzun yoldan dönmek, bir “chicken gybe” (korkak kavança), donanıma değil mesafeye mal olur.', 'Le virement de bord est le plus doux des deux, la bôme passant lentement, voiles faseyantes. Dans la brise, ou avec un équipage débutant, faire le tour par un virement — un « virement lof pour lof » — coûte de la distance, pas du matériel.', 'La virata è la più dolce delle due, con il boma che passa lentamente e le vele che sbattono. Con vento forte, o con un equipaggio alle prime armi, fare il giro lungo con una virata al posto della strambata — la cosiddetta «chicken gybe» — costa distanza, non attrezzatura.', 'A cambada é a mais suave das duas, com a retranca cruzando devagar e as velas panejando. Com vento forte, ou com uma tripulação nova, dar a volta pelo lado mais longo, com uma cambada — o “chicken gybe” —, custa distância, não equipamento.'),
      ], tip: t('A penalty turn is one of each, a tack and a gybe, turning the same way (rule 44.2).',
        'Штрафной оборот — это один оверштаг и один фордевинд в одну сторону (правило 44.2).', 'Un giro de penalización es uno de cada, una virada y una trasluchada, girando hacia el mismo lado (regla 44.2).', 'Ein Strafkringel besteht aus je einer Wende und einer Halse, in dieselbe Richtung gedreht (Regel 44.2).', 'Bir ceza dönüşü her birinden biridir, bir tramola ve bir kavança, aynı yöne dönerek (kural 44.2).', 'Un tour de pénalité, c’est un de chaque, un virement et un empannage, en tournant dans le même sens (règle 44.2).', 'Un giro di penalità è una di ciascuna, una virata e una strambata, girando nello stesso verso (regola 44.2).', 'Um giro de penalidade é um de cada, uma cambada e um jibe, virando no mesmo sentido (regra 44.2).') },
      { id: 'rule', h: t('Keep clear while you tack (rule 13)', 'Поворачивая, уступай (правило 13)', 'Mantente separado mientras viras (regla 13)', 'Halte dich beim Wenden frei (Regel 13)', 'Tramola atarken uzak dur (kural 13)', 'Se maintenir à l’écart en virant (règle 13)', 'Tieniti discosto mentre viri (regola 13)', 'Mantenha-se afastado ao cambar (regra 13)'), p: [
        t('From the moment she passes head to wind until she is on a close-hauled course, a tacking boat keeps clear of everyone, on either tack (rule 13). Once on her new course she may have right of way, but must at first give the other boat room to keep clear (rule 15). A gybe has no rule of its own: she is on the new tack as soon as the boom comes across.',
          'С момента, когда лодка прошла положение левентик, и пока не легла в бейдевинд, она уступает всем, на каком бы галсе они ни шли (правило 13). Легла на новый курс — может получить право дороги, но сначала должна дать другой лодке место, чтобы уступить (правило 15). Для фордевинда отдельного правила нет: лодка на новом галсе, как только гик перешёл на другой борт.', 'Desde el momento en que pasa proa al viento hasta que está de ceñida, un barco que vira se mantiene separado de todos, en cualquier amura (regla 13). Una vez en su nuevo rumbo puede tener derecho de paso, pero al principio debe dar al otro barco espacio para mantenerse separado (regla 15). Una trasluchada no tiene regla propia: está en la nueva amura en cuanto la botavara cruza.', 'Vom Moment an, in dem es durch den Wind geht, bis es auf einem Kurs hoch am Wind liegt, hält sich ein wendendes Boot von allen frei, auf beiden Bugen (Regel 13). Sobald es auf seinem neuen Kurs liegt, darf es Wegerecht haben, muss dem anderen Boot aber zunächst Raum geben, sich freizuhalten (Regel 15). Eine Halse hat keine eigene Regel: Das Boot ist auf dem neuen Bug, sobald der Baum hinüberkommt.', 'Tekne rüzgârın içinden geçtiği andan orsa rotasına gelene kadar, tramola atan tekne her kontradaki herkesten uzak durur (kural 13). Yeni rotasına geçince geçiş hakkı olabilir, ama önce diğer tekneye uzak durması için alan vermelidir (kural 15). Kavançanın kendi kuralı yok: bom karşıya geçer geçmez yeni kontradadır.', 'À partir du moment où il passe face au vent et jusqu’à ce qu’il soit sur une route au près, un bateau qui vire se maintient à l’écart de tous les autres, sur l’une ou l’autre amure (règle 13). Une fois sur sa nouvelle route, il peut avoir la priorité, mais doit d’abord laisser à l’autre bateau la place de se maintenir à l’écart (règle 15). L’empannage n’a pas de règle propre : le bateau est sur la nouvelle amure dès que la bôme est passée.', 'Dal momento in cui passa prua al vento fino a quando è su una rotta di bolina stretta, una barca che vira si tiene discosta da tutte le altre, con qualsiasi mura (regola 13). Una volta sulla nuova rotta può avere diritto di rotta, ma deve all’inizio dare all’altra barca lo spazio per tenersi discosta (regola 15). La strambata non ha una regola sua: la barca è sulle nuove mure appena il boma è passato.', 'A partir do momento em que passa de proa ao vento até estar num rumo de orça, um barco cambando se mantém afastado de todos, em qualquer amura (regra 13). Já no novo rumo, ele pode ter direito de passagem, mas de início precisa dar ao outro barco espaço para se manter afastado (regra 15). O jibe não tem regra própria: o barco está na nova amura assim que a retranca cruza.'),
        t('The computer boats in the game race by it: tack too close under their bows and they hail “You’re tacking — keep clear!”, and the foul is yours.',
          'Компьютерные лодки в игре гоняются по нему: повернёшь слишком близко у них перед носом — услышишь «Ты в повороте — уходи!», и нарушение твоё.', 'Los barcos del ordenador del juego regatean según ella: vira demasiado cerca de su proa y te avisan “¡Estás virando, mantente separado!”, y la falta es tuya.', 'Die Computerboote im Spiel segeln danach: Wendest du zu dicht unter ihrem Bug, rufen sie „Du wendest — halte dich frei!“, und das Foul ist deins.', 'Oyundaki bilgisayar tekneleri buna göre yarışır: pruvalarının altına çok yakın tramola atarsan “Tramola atıyorsun, uzak dur!” diye çağrı yaparlar ve faul senindir.', 'Les bateaux de l’ordinateur du jeu courent selon cette règle : vire trop près sous leur étrave et ils hèlent « Tu vires — écarte-toi ! », et la faute est pour toi.', 'Le barche del computer nel gioco regatano seguendola: vira troppo vicino sotto la loro prua e chiamano «Stai virando — tieniti discosto!», e l’infrazione è tua.', 'Os barcos do computador no jogo seguem essa regra: cambe perto demais da proa deles e eles chamam “Você está cambando — mantenha-se afastado!”, e a infração é sua.'),
      ], tip: t('Tacking just ahead and to leeward of a boat, on her lee bow, puts her in your dirty air — but only if you are close-hauled before she has to change course to avoid you. A length short and it’s a foul.',
        'Поворот чуть впереди лодки и под ветер от неё ставит её в твою ветровую тень — но только если ты ляжешь в бейдевинд раньше, чем ей придётся менять курс, чтобы тебя избежать. Не хватит корпуса — нарушение.', 'Virar justo por delante y a sotavento de un barco, en su amura de sotavento, lo pone en tu aire sucio — pero solo si estás de ceñida antes de que él tenga que cambiar de rumbo para evitarte. Una eslora de menos y es una falta.', 'Direkt vor und in Lee eines Bootes zu wenden, auf seinem Leebug, bringt es in deinen Abwind — aber nur, wenn du hoch am Wind liegst, bevor es den Kurs ändern muss, um dir auszuweichen. Eine Länge zu kurz, und es ist ein Foul.', 'Bir teknenin hemen önünde ve rüzgâraltında, onun lee pruvasında tramola atmak onu kirli rüzgârına sokar, ama yalnızca o seni kaçmak için rota değiştirmek zorunda kalmadan önce orsada olursan. Bir boy kısa kalırsan bu bir faul.', 'Virer juste devant et sous le vent d’un bateau, sous son étrave, le met dans ton vent perturbé — mais seulement si tu es au près avant qu’il doive changer de route pour t’éviter. Une longueur trop court, et c’est une faute.', 'Virare appena davanti e sottovento a una barca, sotto la sua prua, la mette nella tua aria sporca — ma solo se sei di bolina stretta prima che lei debba cambiare rotta per evitarti. Una lunghezza di meno ed è un’infrazione.', 'Cambar logo à frente e a sotavento de um barco, na bochecha de sotavento dele, coloca o barco no seu vento sujo — mas só se você estiver na orça antes de ele ter de mudar de rumo para evitar você. Um comprimento a menos e é infração.') },
    ],
    more: [
      { label: t('Sailing downwind: gybing with the gennaker', 'Попутные курсы: фордевинд с генакером', 'Navegar de popa: trasluchar con el gennaker', 'Vor dem Wind segeln: halsen mit dem Gennaker', 'Pupada yelken açmak: gennaker ile kavança', 'Naviguer au portant : empanner sous gennaker', 'Navigare in poppa: strambare con il gennaker', 'Velejar em popa: jibe com o gennaker'), href: '/learn/downwind' },
      { label: t('Right of way, rule by rule', 'Право дороги, правило за правилом', 'Derecho de paso, regla por regla', 'Wegerecht, Regel für Regel', 'Geçiş hakkı, kural kural', 'La priorité, règle par règle', 'Il diritto di rotta, regola per regola', 'Direito de passagem, regra por regra'), href: rr(lang, 'rightofway') },
      { label: t('Glossary: tack and gybe', 'Словарь: оверштаг и фордевинд', 'Glosario: virar y trasluchar', 'Glossar: Wende und Halse', 'Sözlük: tramola ve kavança', 'Glossaire : virement de bord et empannage', 'Glossario: virata e strambata', 'Glossário: cambada e jibe'), href: '/learn/glossary#tack' },
    ],
    try: { label: t('Try the drills', 'Попробуй тренировки', 'Prueba los ejercicios', 'Probier die Übungen', 'Alıştırmaları dene', 'Essaie les entraînements', 'Prova gli esercizi', 'Experimente os treinos'), href: '/race/drills', text: t(
      'The penalty turn drill times a tack and a gybe and the climb back to speed; the shifts drill is a beat of tacks on the headers.',
      'Тренировка «Штрафной оборот» засекает оверштаг, фордевинд и разгон после них, а «Сдвиги ветра» — это лавировка с поворотами на заходах.', 'El ejercicio del giro de penalización cronometra una virada y una trasluchada y la subida hasta recuperar la velocidad; el ejercicio de las roladas es una ceñida de viradas en las roladas desfavorables.', 'Die Strafkringel-Übung misst eine Wende und eine Halse und den Weg zurück auf Fahrt; die Winddreher-Übung ist ein Kreuz aus Wenden auf den Drehern.', 'Ceza dönüşü alıştırması bir tramola ve bir kavançayı ve hıza geri tırmanışı zamanlar; rüzgâr dönüşleri alıştırması aleyhte dönüşlerde tramolalardan oluşan bir orsa ayağıdır.', 'L’entraînement au tour de pénalité chronomètre un virement, un empannage et la reprise de vitesse ; celui des bascules est un bord de près à virer sur les refus.', 'L’esercizio sul giro di penalità cronometra una virata, una strambata e la ripresa della velocità; quello sui salti di vento è un lato di bolina virando sui salti a scarso.', 'O treino de giro de penalidade cronometra uma cambada, um jibe e a volta à velocidade; o treino de rondadas é uma orça cambando nas rondadas contra.') },
  };
}
